m_dfree:
;------------------------------------------------------------------------------
; DFREE(drive): free space on a drive in bytes.
; Entry: d0.w = drive (0 = current, 1 = A:, ...)
; Exit: d0.l = free clusters * bytes per sector * sectors per cluster
; The Dfree buffer is the scratch buffer at $4a(a6).
;------------------------------------------------------------------------------
disk_free:
	move.w	d0,-(sp)                        ; drive
	pea	$4a(a6)                         ; Dfree buffer: free clusters, total clusters, sector size, sectors per
                                                ;   cluster
	move.w	#$36,-(sp)                      ; Dfree
	trap	#1                              ; Dfree
	addq.l	#8,sp                           ; drop the arguments
	move.w	$54(a6),d0                      ; bytes per sector (low word)
	mulu.w	$58(a6),d0                      ; * sectors per cluster
	mulu.w	$4c(a6),d0                      ; * free clusters
	rts

; symbol table: name, type, value
	dc.b	$44,$46,$52,$45,$45,$00,$00,$00		; DFREE
	dc.w	$a200				; defined global text
	dc.l	$0
; relocation words, one a code word: 0 none, 1 data, 2 text, 3 bss, 4 external, 5 a long (its low
; word tells), 6 external pc-relative, 7 the first word of an instruction; an external's symbol
; number is the word >> 3
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000

