m_ne:
;------------------------------------------------------------------------------
; Floating point compare for inequality, both operands in memory: loads the right operand from (a1), then the left from
; (a0).
; Entry: a0 -> left float, a1 -> right float (6 bytes each)
; Exit: d0.l = -1 if they differ, else 0; a0, a1 advanced by 6
;------------------------------------------------------------------------------
float_not_equal_stored_pair:
	move.l	(a1)+,d0                        ; right operand from (a1)
	move.w	(a1)+,d1                        ; low mantissa word
	move.w	(a1)+,d2                        ; exponent word

;------------------------------------------------------------------------------
; Floating point compare for inequality with the left operand in memory.
; Entry: a0 -> left float, d0-d2 = right float
; Exit: d0.l = -1 if they differ, else 0; a0 advanced by 6
;------------------------------------------------------------------------------
float_not_equal_stored:
	move.l	(a0)+,d3                        ; left operand from (a0)
	move.w	(a0)+,d4                        ; low mantissa word
	move.w	(a0)+,d5                        ; exponent word

;------------------------------------------------------------------------------
; Floating point compare for inequality.
; Entry: d3-d5 = left, d0-d2 = right
; Exit: d0.l = -1 if they differ, else 0
;------------------------------------------------------------------------------
float_not_equal:
	cmp.w	d2,d5                           ; different signed exponents: different numbers
	bne.s	.true
	tst.w	d2                              ; both zero: equal
	beq.s	.both_zero
	cmp.l	d3,d0                           ; compare the mantissas
	bne.s	.true
	cmp.w	d4,d1                           ; low words
	bne.s	.true
.false:
	moveq	#0,d0                           ; equal
	rts
.both_zero:
	tst.w	d5                              ; both exponents zero?
	beq.s	.false                          ; both zero: equal
.true:
	moveq	#-1,d0                          ; different
	rts

; symbol table: name, type, value
