	dc.l	$0
	dc.b	$56,$46,$4e,$45,$00,$00,$00,$00		; VFNE
	dc.w	$a200				; defined global text
	dc.l	$6
	dc.b	$46,$4e,$45,$00,$00,$00,$00,$00		; FNE
	dc.w	$a200				; defined global text
	dc.l	$c
