m_eq:
;------------------------------------------------------------------------------
; Floating point compare for equality, both operands in memory.
; Entry: a0, a1 -> the two floats
; Exit: d0.l = -1 if equal, else 0
;------------------------------------------------------------------------------
float_equal_stored_pair:
	move.l	(a1)+,d0                        ; right operand from (a1)
	move.w	(a1)+,d1                        ; low mantissa word
	move.w	(a1)+,d2                        ; exponent word

;------------------------------------------------------------------------------
; Floating point compare for equality with one operand in memory.
; Entry: a0 -> float, d0-d2 = float
; Exit: d0.l = -1 if equal, else 0
;------------------------------------------------------------------------------
float_equal_stored:
	move.l	(a0)+,d3                        ; left operand from (a0)
	move.w	(a0)+,d4                        ; low mantissa word
	move.w	(a0)+,d5                        ; exponent word

;------------------------------------------------------------------------------
; Floating point compare for equality.
; Entry: d0-d2 and d3-d5 = the two floats
; Exit: d0.l = -1 if equal, else 0
;------------------------------------------------------------------------------
float_equal:
	tst.w	d2                              ; zero has no meaningful mantissa
	beq.s	.accumulator_zero
	cmp.l	d3,d0                           ; compare mantissa and exponent word by word
	bne.s	.false
	cmp.w	d4,d1                           ; low words
	bne.s	.false
	cmp.w	d5,d2                           ; exponents with sign
	bne.s	.false
.true:
	moveq	#-1,d0                          ; equal
	rts
.accumulator_zero:
	tst.w	d5                              ; equal only if the other one is zero too
	beq.s	.true
.false:
	moveq	#0,d0                           ; not equal
	rts

