.swap_check:
	cmpi.l	#$10000,d1                      ; d1 within 16 bits?
	bcs.s	.short_multiply                 ; d1 is the bigger one: is d0 within 16 bits?
	exg	d1,d0                           ; make d1 the 16-bit factor
