	ble.s	multiply_sign_operand           ; operand zero or negative
	ext.l	d2                              ; accumulator zero or negative
	ble.s	multiply_sign_accumulator       ; accumulator zero or negative

;------------------------------------------------------------------------------
; Multiplies two positive floats, skipping partial products of zero words.
; Entry: d0-d2, d3-d5 = positive floats
; Exit: d0-d2 = product
;------------------------------------------------------------------------------
multiply_magnitudes:
	add.w	d5,d2                           ; add the exponents
	subi.w	#$3fe,d2                        ; remove one bias (and one for the mantissa position)
	tst.w	d1                              ; accumulator low word zero?
	beq.w	multiply_short_accumulator      ; acc low word zero: fewer products
	tst.w	d4                              ; operand low word present: full product
	bne.s	multiply_full_mantissa          ; operand low word set: full product
	move.w	d3,d5                           ; op mid word
	beq.s	.operand_mid_zero               ; operand mid word zero
	mulu.w	d0,d5                           ; acc mid * op mid
	moveq	#0,d6                           ; carry source
	swap	d3                              ; op high word
	mulu.w	d3,d1                           ; op high * acc low
	add.l	d5,d1                           ; 2^-32 terms summed
	swap	d0                              ; acc high
	move.w	d3,d5                           ; op high
	mulu.w	d0,d5                           ; acc high * op high (top term)
	addx.l	d6,d5                           ; plus the carry
	move.w	d3,d6                           ; op high
	swap	d3                              ; op mid
	move.w	d0,d7                           ; acc high
	swap	d0                              ; acc mid
	mulu.w	d6,d0                           ; acc mid * op high
	mulu.w	d7,d3                           ; op mid * acc high
	add.l	d3,d0                           ; 2^-16 terms summed
	bcc.w	normalize_product               ; no carry: normalize
	addi.l	#$10000,d5                      ; carry into the top term
	bra.s	normalize_product               ; normalize the sum
.operand_mid_zero:
	swap	d3                              ; operand mid word zero
	mulu.w	d3,d1                           ; op high * acc low
	swap	d0                              ; acc high
	move.w	d3,d5                           ; op high
	mulu.w	d0,d5                           ; acc high * op high
	swap	d0                              ; acc mid
	mulu.w	d3,d0                           ; acc mid * op high
	bra.s	normalize_product               ; normalize the sum
.operand_sign:
	beq.s	.zero                           ; sign handling for the unlabelled entry just before
                                                ;   multiply_full_precision
	neg.w	d2                              ; flip the accumulator sign
	beq.s	.zero                           ; accumulator zero
	bmi.s	.negative_result                ; accumulator was positive: negative product
	neg.w	d5                              ; both negative: positive product
	bra.s	multiply_full_precision         ; positive product
.negative_result:
	neg.w	d2                              ; magnitudes, multiply, then negate
	neg.w	d5                              ; operand magnitude
	bsr.s	multiply_full_precision         ; multiply the magnitudes
	neg.w	d2                              ; negative product
	rts
.accumulator_sign:
	beq.s	.zero                           ; accumulator zero
	neg.w	d2                              ; accumulator negative: magnitude
	bsr.s	multiply_full_precision         ; multiply the magnitude
	neg.w	d2                              ; negative product
	rts
.zero:
	moveq	#0,d2                           ; zero product
	rts
	ext.l	d5                              ; unlabelled entry: full-precision multiply with signs
	ble.s	.operand_sign                   ; operand zero or negative
	ext.l	d2
	ble.s	.accumulator_sign               ; accumulator zero or negative

;------------------------------------------------------------------------------
; Multiplies two positive floats using every partial product.
; Entry: d0-d2, d3-d5 = positive floats
; Exit: d0-d2 = product
