multiply_full_precision:
	add.w	d5,d2                           ; add the exponents
	subi.w	#$3fe,d2                        ; remove the bias

;------------------------------------------------------------------------------
; Forms the 48 x 48 bit mantissa product and goes on to normalize_product.
; Entry: d0/d1, d3/d4 = mantissas, d2 = exponent
