	swap	d3                              ; op high word
	mulu.w	d3,d1                           ; operand high * accumulator low word
	add.l	d5,d1                           ; 2^-32 terms so far
	swap	d0                              ; acc high word
	mulu.w	d0,d4                           ; accumulator high * operand low
	move.w	d3,d5                           ; op high
	mulu.w	d0,d5                           ; acc high * op high (top term)
	addx.l	d6,d5                           ; plus the carry
	add.l	d4,d1                           ; plus acc high * op low
	addx.l	d6,d5                           ; plus the carry
	move.w	d3,d6                           ; op high
	swap	d3                              ; op mid
	move.w	d0,d7                           ; acc high
	swap	d0                              ; acc mid
	mulu.w	d6,d0                           ; top partial products
	mulu.w	d7,d3                           ; op mid * acc high
	add.l	d3,d0                           ; 2^-16 terms summed
	bcc.s	normalize_product               ; no carry: normalize
	addi.l	#$10000,d5                      ; carry into the top long

