	dc.l	$126,$0,$1a,$134		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_error:
; Resume point kept by set_resume_point: return address, a3 and sp at the last call; zero when none. Followed by a
; pointer to the error message table.
error_resume_context:
	dc.w	$0000,$0000                     ; return address of the resume point
RegA3:
	dc.w	$0000,$0000                     ; a3 of the resume point
RegA7:
	dc.w	$0000,$0000,$0000,$0000         ; sp of the resume point; then the message table pointer

;------------------------------------------------------------------------------
; Prints the text at a1 with AesNO1 (unlabelled entry), then raises error 69.
;------------------------------------------------------------------------------
error_print_text:
	dc.w	$6100,$0000                     ; bsr.w error_print_text+2 -> AesNO1 (filled in by the linker),
                                                ;   unlabelled entry: print the text at a1, then error 69

;------------------------------------------------------------------------------
; Error 69 (used by ENDFUNC: a FUNCTION ended without RETURN).
;------------------------------------------------------------------------------
ENDFUNC:
	moveq	#69,d0                          ; error 69

;------------------------------------------------------------------------------
; Runtime error exit. Stores the error number, restores the runtime registers and either calls the ON ERROR handler or
; shows an alert "[1][Error nnn][Return]" (or the table text) and ends the program with the error number.
; Entry: d0.b = error number (negative GEMDOS errors pass through)
; Exit: does not return
;------------------------------------------------------------------------------
runtime_error:
	move.b	d0,$6                           ; error number for ERR
	dc.w	$bdfc,$0000,$0000               ; cmpa.l #$0,a6 -> BssA6 (filled in by the linker), a6 still the runtime
                                                ;   block?
	beq.s	.runtime_block_ok               ; yes
	st	$8                              ; bus error vector, no: note the broken state
	bra.s	.reset_stack
.runtime_block_ok:
	movem.l	error_resume_context(pc),d1-d3  ; d1 = return address, d2 = a3, d3 = sp of the resume point
	tst.l	d1                              ; none kept
	beq.s	.reset_stack
	movea.l	d2,a3                           ; go back to the resume state
	movea.l	d3,sp
	bra.s	.reload_registers
.reset_stack:
	bsr.s	reset_runtime_stack             ; fresh stack and heap pointer
.reload_registers:
	bsr.s	reload_base_registers           ; a4/a5/a6 again
	move.l	$12,d5                          ; ON ERROR handler set?
	bne.s	.call_handler                   ; yes: call it
	bsr.s	build_error_alert               ; no: build the alert text
	move.l	a1,$1134(a6)                    ; addrin[0] = alert text
	move.w	#$1,$10e4(a6)                   ; intin[0] = default button 1
	moveq	#52,d0                          ; form_alert
	bsr.w	m_error+$126                    ; AES call (code linked straight after this module)
.call_handler:
	pea	error_terminate(pc)             ; handler returns to error_terminate
	move.l	$12,d5                          ; handler address
	beq.s	error_terminate                 ; none
	movea.l	d5,a0                           ; a0 = handler
	jmp	(a0)                            ; call the ON ERROR handler

;------------------------------------------------------------------------------
; Ends the program after an error.
; Exit: Pterm with d0 = -256 + error number
;------------------------------------------------------------------------------
error_terminate:
	moveq	#-1,d0                          ; upper bytes all set
	move.b	$6,d0                           ; error number in the low byte

runtime_error_call_systemn:
	dc.w	$6000,$0000                     ; bra.w runtime_error_call_systemn+2 -> SYSTEMN (filled in by the
                                                ;   linker), Pterm with that code

;------------------------------------------------------------------------------
; Reloads a4/a5/a6, resets a3 to the heap start and sp to the runtime stack top, then returns to the caller.
; Exit: a3 = $1c(a6), sp = a6 + $3a90
;------------------------------------------------------------------------------
reset_runtime_stack:
	movea.l	(sp)+,a0                        ; return address (the stack is about to be reset)
	bsr.s	reload_base_registers           ; a4 / a5 / a6 again
	movea.l	$1c(a6),a3                      ; heap pointer back to the start
	lea	$3a90(a6),sp                    ; runtime stack top
	jmp	(a0)                            ; return

;------------------------------------------------------------------------------
; Sets the three base registers.
; Exit: a6 = runtime block, a4 = library + $8000, a5 = variables + $8000
;------------------------------------------------------------------------------
reload_base_registers:
	dc.w	$4df9,$0000,$0000               ; lea	$0,a6 -> BssA6 (filled in by the linker)
	dc.w	$49f9,$0000,$0000               ; lea	$0,a4 -> BaseA4 (filled in by the linker)
	dc.w	$4bf9,$0000,$0000               ; lea	$0,a5 -> BssA5 (filled in by the linker)
	move.l	#$8000,d2                       ; base registers point $8000 in ...
	adda.l	d2,a4
	adda.l	d2,a5
	rts

; Alert box text for a runtime error with no table message: "[1][Error ".
error_alert_text:
	dc.b	'[1][Error '

; Sign and three digits of the error alert, written by build_error_alert.
error_alert_number:
	dc.w	$2b31,$3131

; End of the error alert: "][Return]", zero-terminated.
error_alert_end:
	dc.b	'][Return]',0

;------------------------------------------------------------------------------
; Builds the alert text for a runtime error. A message from the error table becomes "[1][text][Return]" in the scratch
; buffer; otherwise the number is written into error_alert_number.
; Entry: d0.b = error number
; Exit: a1 -> alert text
;------------------------------------------------------------------------------
build_error_alert:
	lea	error_resume_context-m_error,a2 ; error message table
.search_message:
	move.b	(a2)+,d1                        ; error number of the entry
	cmpi.b	#$7f,d1                         ; $7f ends the table
	beq.s	.number_alert                   ; not found: alert with the number
	cmp.b	d0,d1                           ; this error?
	beq.s	.message_alert                  ; found: alert with the message
.skip_text:
	tst.b	(a2)+                           ; skip its text
	bne.s	.skip_text
	bra.s	.search_message                 ; next entry
.number_alert:
	lea	error_alert_number(pc),a0       ; digits go here
	moveq	#32,d1                          ; sign: space
	ext.w	d0                              ; error number as a signed word
	bpl.s	.write_sign                     ; positive
	moveq	#45,d1                          ; negative: minus
	neg.w	d0                              ; magnitude
.write_sign:
	move.b	d1,(a0)+                        ; sign character
	ext.l	d0
	divu.w	#$64,d0                         ; hundreds
	ori.b	#$30,d0                         ; hundreds digit to ASCII
	move.b	d0,(a0)+
	swap	d0                              ; remainder
	ext.l	d0
	divu.w	#$a,d0                          ; tens
	ori.b	#$30,d0                         ; tens digit to ASCII
	move.b	d0,(a0)+
	swap	d0                              ; remainder: units
	ori.b	#$30,d0                         ; units
	move.b	d0,(a0)+
	lea	error_alert_text(pc),a1         ; a1 -> "[1][Error snnn][Return]"
	rts
.message_alert:
	lea	$4a(a6),a0                      ; build in the scratch buffer
	movea.l	a0,a1                           ; a1 -> alert text
	move.l	#$5b315d5b,(a0)+                ; "[1]["
.copy_message:
	move.b	(a2)+,(a0)+                     ; copy the message ...
	bne.s	.copy_message                   ; ... with its terminator
	subq.l	#1,a0                           ; back over the terminator
	lea	error_alert_end(pc),a2          ; then "][Return]"
.copy_tail:
	move.b	(a2)+,(a0)+                     ; copy "][Return]" ...
	bne.s	.copy_tail                      ; ... with its terminator
	rts

