m_deutsch:
; ERRNAMES: the German error message table (Atari character set). Each entry is the error number as a
; byte (negative numbers for BIOS / GEMDOS errors), then the text, zero-terminated, with | starting a new
; alert line; $7f ends the table.
ERRNAMES:
	dc.b	$00                             ; error 0
	dc.b	'Division durch Null',0         ; Division by zero
	dc.b	$01,$9a                         ; error 1: overflow (Ue = $9a)
	dc.b	'berlauf',0
	dc.b	$05                             ; error 5
	dc.b	'Quadratwurzel nur f'           ; Square root only for positive numbers (ue = $81)
	dc.b	$81
	dc.b	'r|positive Zahlen',0
	dc.b	$06                             ; error 6
	dc.b	'Logarithmen nur f'             ; Logarithms only for numbers greater than zero
	dc.b	$81
	dc.b	'r|Zahlen gr'
	dc.w	$949e
	dc.b	'er Null',0
	dc.b	$07                             ; error 7
	dc.b	'Unbekannter Fehler ',0         ; Unknown error
	dc.b	$08                             ; error 8
	dc.b	'Speicher voll',0               ; Memory full
	dc.b	10,'String zu lang|max. 32767 Zeichen',0 ; error 10: string too long, max. 32767 characters
	dc.b	$0e                             ; error 14
	dc.b	'Feld zweimal dimensioniert',0  ; Array dimensioned twice
	dc.b	$0f                             ; error 15
	dc.b	'Feld nicht dimensioniert',0    ; Array not dimensioned
	dc.b	$11                             ; error 17
	dc.b	'Dim zu gro'                    ; Dim too large (sz = $9e)
	dc.w	$9e00
	dc.b	$15
	dc.b	'Bei Open nur erlaubt:|"I"nput  "O"utput "R"andom|"A"ppend "U"pdate',0 ; OPEN only allows "I"nput
                                                ;   "O"utput "R"andom "A"ppend "U"pdate
	dc.b	$16                             ; error 22
	dc.b	'File schon ge'                 ; File already open (oe = $94)
	dc.b	$94
	dc.b	'ffnet',0
	dc.b	$17                             ; error 23
	dc.b	'File # falsch',0               ; File # wrong
	dc.b	$18                             ; error 24
	dc.b	'File nicht ge'                 ; File not open
	dc.b	$94
	dc.b	'ffnet',0
	dc.b	$19                             ; error 25
	dc.b	'Falsche Eingabe, keine Zahl',0 ; Wrong input, not a number
	dc.b	$1a                             ; error 26
	dc.b	'Fileende erreicht|EOF',0       ; End of file reached, EOF
	dc.b	$1c,$46,$65,$6c,$64,$20,$6d,$75,$9e ; error 28: array must be ...
	dc.b	' eindimensional sein',0        ; ... one-dimensional
	dc.b	'"Zu wenig Data',0              ; error 34 ('"'): too few DATA
	dc.b	'#Data nicht numerisch',0       ; error 35 ('#'): DATA not numeric
	dc.b	'%Diskette voll',0              ; error 37 ('%'): disk full
	dc.b	'0Open "R" - Satzl'             ; error 48 ('0'): OPEN "R" record length wrong (ae = $84)
	dc.b	$84
	dc.b	'nge falsch',0
	dc.b	'1Zu viele "R"-Files (max. 31)',0 ; error 49 ('1'): too many "R" files (max. 31)
	dc.b	'2Kein "R"-File',0              ; error 50 ('2'): no "R" file
	dc.b	'4Fields gr'                    ; error 52 ('4'): fields larger than the record length
	dc.b	$94,$9e
	dc.b	'er als Satzl'
	dc.b	$84,$6e,$67,$65,$00
	dc.b	'6GET/PUT Field-String|L'       ; error 54 ('6'): GET/PUT field string length wrong
	dc.b	$84
	dc.b	'nge falsch',0
	dc.b	'7GET/PUT Satznummer falsch',0  ; error 55 ('7'): GET/PUT record number wrong
	dc.b	'<Sprite-String-L'              ; error 60 ('<'): sprite string length wrong
	dc.b	$84
	dc.b	'nge falsch',0
	dc.b	'=Fehler bei RESERVE',0         ; error 61 ('='): error in RESERVE
	dc.b	'>Menu falsch',0                ; error 62 ('>'): menu wrong
	dc.b	'?Reserve falsch',0             ; error 63 ('?'): RESERVE wrong
	dc.b	'@Pointer falsch',0             ; error 64 ('@'): pointer wrong
	dc.b	'CASIN/ACOS falsch',0           ; error 67 ('C'): ASIN/ACOS wrong
	dc.b	'EENDFUNC ohne RETURN',0        ; error 69 ('E'): ENDFUNC without RETURN
	dc.b	'PMatrizenoperationen nur f'    ; error 80 ('P'): matrix operations only for 1- or 2-dim arrays
	dc.b	$81
	dc.b	'r|ein- oder zweidimensionale|Felder',0
	dc.b	'QMatrizen haben nicht die|gleiche Ordnung',0 ; error 81 ('Q'): matrices do not have the same order
	dc.b	'RVektorprodukt nicht definiert',0 ; error 82 ('R'): vector product not defined
	dc.b	'SMatrizenprodukt nicht definiert',0 ; error 83 ('S'): matrix product not defined
	dc.b	'TScalarprodukt nicht definiert',0 ; error 84 ('T'): scalar product not defined
	dc.b	'UTransposition nur f'          ; error 85 ('U'): transposition only for two-dimensional matrices
	dc.b	$81
	dc.b	'r|zweidimensionale Matrizen',0
	dc.b	'VMatrix nicht quadratisch',0   ; error 86 ('V'): matrix not square
	dc.b	'WTransposition nicht definiert',0 ; error 87 ('W'): transposition not defined
	dc.b	'XFACT/COMBIN/VARIAT|nicht definiert',0 ; error 88 ('X'): FACT/COMBIN/VARIAT not defined
