;------------------------------------------------------------------------------
; Signed long division with the operands the other way round.
; Entry: d1.l = dividend, d0.l = divisor
; Exit: d0.l = quotient; error 0 for a zero divisor
;------------------------------------------------------------------------------
long_divide_swapped:
	exg	d1,d0                           ; operands the other way round

;------------------------------------------------------------------------------
; Signed long division, truncating toward zero (DIV and \ on integers).
; Entry: d0.l = dividend, d1.l = divisor
; Exit: d0.l = quotient; a zero divisor raises error 0
; Uses d1-d5.
;------------------------------------------------------------------------------
long_divide:
	move.l	d1,d2                           ; d2 = divisor
	beq.s	division_by_zero                ; division by zero
	bmi.s	.long_division                  ; negative divisor: full division
	cmp.l	d0,d2                           ; divisor >= dividend (unsigned)?
	bcc.s	.divisor_not_smaller            ; divisor not smaller: 0 or 1
	ext.l	d1                              ; divisor fits in a word?
	cmp.l	d2,d1                           ; sign extended low word the same?
	bne.s	.long_division                  ; no: long division
	divs.w	d2,d0                           ; one divs
	bvs.s	.long_division                  ; quotient too big for a word
	ext.l	d0                              ; quotient sign extended
	rts
.divisor_not_smaller:
	bne.s	.zero                           ; equal: quotient 1
	bgt.s	.long_division
	moveq	#1,d0                           ; quotient 1
	rts
.zero:
	moveq	#0,d0                           ; divisor larger: quotient 0
	rts
.long_division:
	move.l	d2,d1                           ; negative divisor: divide by its magnitude
	bge.s	divide_by_positive              ; positive: straight on
	neg.l	d1                              ; divisor magnitude
	bsr.s	divide_by_positive              ; divide the magnitude
	neg.l	d0                              ; and negate
	rts

;------------------------------------------------------------------------------
; Signed long division by a positive divisor.
; Entry: d0.l = dividend, d1.l = divisor > 0
; Exit: d0.l = quotient
;------------------------------------------------------------------------------
divide_by_positive:
	tst.l	d0                              ; dividend positive?
	bgt.s	unsigned_divide                 ; positive dividend
	neg.l	d0                              ; negative: divide the magnitude and negate
	bsr.s	unsigned_divide                 ; divide the magnitude
	neg.l	d0                              ; negative dividend: negative quotient
	rts

;------------------------------------------------------------------------------
; Unsigned long division by shift and subtract.
; Entry: d0.l = dividend, d1.l = divisor
; Exit: d0.l = quotient
; Uses d4/d5.
;------------------------------------------------------------------------------
unsigned_divide:
	moveq	#0,d5                           ; d5 = quotient
	moveq	#1,d4                           ; d4 = current quotient bit
	cmp.l	d1,d0                           ; dividend below the divisor: quotient 0
	bcs.s	.next_bit
