	bcs.s	.next_bit                       ; does not fit: skip
	or.l	d4,d5                           ; set the quotient bit
	sub.l	d1,d0                           ; subtract the divisor
.next_bit:
	lsr.l	#1,d1                           ; next lower bit
	lsr.l	#1,d4                           ; and the quotient bit
	bne.s	.subtract_loop                  ; until the bit is gone
	move.l	d5,d0                           ; the quotient
	rts

