	dc.b	$49,$4e,$49,$54,$41,$45,$53,$2e,$4f,$00,$00,$00,$00,$00	; library entry: the name INITAES.O
	dc.w	$7348,$1675,$0000,$01b6,$0000,$06ea,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$2e2,$0,$2,$10a		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_initaes:
;------------------------------------------------------------------------------
; Jump to gem_startup.
;------------------------------------------------------------------------------
jump_gem_startup:
	bra.s	gem_startup                     ; start-up

;------------------------------------------------------------------------------
; Restores the keyboard and vectors, closes the virtual workstation and calls appl_exit.
;------------------------------------------------------------------------------
gem_shutdown:
	bsr.w	restore_keyboard                ; exit hook, then conterm back
	bsr.w	m_initaes+$2e6                  ; shutdown code linked straight after this module
	bra.w	close_vdi_and_aes               ; v_clsvwk and appl_exit

;------------------------------------------------------------------------------
; Unlabelled entry: AesYES (restart GEM) and AesYES1, then on into gem_startup.
;------------------------------------------------------------------------------
gem_init_restart_gem:
	dc.w	$6100,$0000                     ; bsr.w gem_init_restart_gem+2 -> AesYES (filled in by the linker),
                                                ;   unlabelled entry: restart GEM, then an AES call

gem_init_call_aesyes1:
	dc.w	$6100,$0000                     ; bsr.w	gem_init_call_aesyes1+2 -> AesYES1 (filled in by the linker)

;------------------------------------------------------------------------------
; Relocates the GEM parameter blocks, calls appl_init and graf_handle, opens a virtual workstation for the current
; resolution, keeps its work_out and ptsout, sets the graphics defaults and turns on conterm shift reporting.
; Exit: VDI handle in $620(a6), $64e(a6) and $69c(a6)
;------------------------------------------------------------------------------
gem_startup:
	bsr.w	relocate_gem_blocks             ; block offsets -> addresses
	lea	$622(a6),a0                     ; AES global ap_ptree
	move.l	a0,$670(a6)                     ; global[...] pointer for appl_init
	moveq	#10,d0                          ; appl_init
	bsr.s	runtime_aes_call                ; AES call
	moveq	#77,d0                          ; graf_handle
	bsr.s	runtime_aes_call                ; AES call
	move.w	d0,$64e(a6)                     ; physical handle into contrl[6]
	move.w	#$4,-(sp)                       ; Getrez
	trap	#14                             ; Getrez
	addq.l	#2,sp                           ; drop the argument
	addq.w	#2,d0                           ; device = Getrez + 2
	lea	$6a8(a6),a0                     ; work_in[0]
	move.w	d0,(a0)+                        ; work_in[0] = device
	moveq	#9,d1                           ; work_in[1-10] = 1
	moveq	#1,d0
.work_in_loop:
	move.w	d0,(a0)+
	dbra	d1,.work_in_loop
	add.w	d0,-(a0)                        ; work_in[10] = 2: raster coordinates
	moveq	#100,d0                         ; v_opnvwk
	moveq	#11,d1                          ; 11 intin words
	moveq	#0,d2                           ; no ptsin
	bsr.w	runtime_vdi_call                ; open the virtual workstation
	move.w	$64e(a6),d0                     ; workstation handle
	move.w	d0,$69c(a6)                     ; for the user VDI block
	move.w	d0,$620(a6)                     ; for the graphics commands
	lea	$fa8(a6),a0                     ; work_out
	lea	$12a4(a6),a1                    ; kept work_out
	moveq	#44,d0                          ; 45 words
.copy_work_out:
	move.w	(a0)+,(a1)+
	dbra	d0,.copy_work_out               ; 45 work_out words
	lea	$10a8(a6),a0                    ; ptsout
	moveq	#11,d0                          ; 12 words
.copy_pts_out:
	move.w	(a0)+,(a1)+
	dbra	d0,.copy_pts_out                ; then 12 ptsout words

gem_init_call_graphini:
	dc.w	$6100,$0000                     ; bsr.w gem_init_call_graphini+2 -> GRAPHINI (filled in by the linker),
                                                ;   graphics defaults
	bsr.w	conterm_shift_on                ; conterm shift bit on
	bra.w	m_initaes+$2e2                  ; return through the code linked after this module

;------------------------------------------------------------------------------
; Branch to NoWind (not reached from this module).
;------------------------------------------------------------------------------
gem_init_no_window:
	dc.w	$6000,$0000                     ; bra.w	gem_init_no_window+2 -> NoWind (filled in by the linker), spare

;------------------------------------------------------------------------------
; Closes the virtual workstation (v_clsvwk) and calls appl_exit.
;------------------------------------------------------------------------------
close_vdi_and_aes:
	moveq	#101,d0                         ; v_clsvwk
	bsr.s	runtime_vdi_call_no_args        ; close the virtual workstation
	moveq	#19,d0                          ; appl_exit

;------------------------------------------------------------------------------
; Calls an AES function through the runtime's own parameter block, filling control[1-3] from the size table.
; Entry: d0.w = opcode, arrays at $10e4/$1134(a6) filled
; Exit: d0.w = intout[0]
;------------------------------------------------------------------------------
runtime_aes_call:
	lea	$65a(a6),a1                     ; control[0] = opcode
	move.w	d0,(a1)+
	lea	aes_size_index_base+4(pc),a0    ; offset of the size entry
	move.b	0(a0,d0.w),d0                   ; entry offset for the opcode
	lea	aes_array_sizes(pc),a0          ; size table
	adda.w	d0,a0                           ; a0 -> the opcode's entry
	move.b	(a0)+,d0                        ; control[1] = intin count
	move.w	d0,(a1)+
	move.b	(a0)+,d0                        ; control[2] = high nibble, control[3] = low nibble
	moveq	#15,d1
	and.b	d0,d1                           ; d1 = addrin count
	lsr.b	#4,d0                           ; d0 = intout count
	move.w	d0,(a1)+                        ; control[2]
	move.w	d1,(a1)+                        ; control[3]

runtime_aes_show_mouse:
	dc.w	$6100,$0000                     ; bsr.w runtime_aes_show_mouse+2 -> QShowm (filled in by the linker),
                                                ;   show the mouse if it should be
	move.l	#runtime_aes_block_base+2-m_initaes,d1 ; runtime AES parameter block
	move.w	#$c8,d0                         ; AES
	trap	#2                              ; AES/VDI
	movem.w	$110c(a6),d0                    ; intout[0]
	rts

;------------------------------------------------------------------------------
; Calls a VDI function through the runtime's own block with no intin or ptsin.
; Entry: d0.w = opcode
;------------------------------------------------------------------------------
runtime_vdi_call_no_args:
	moveq	#0,d1                           ; no intin
	moveq	#0,d2                           ; no ptsin

;------------------------------------------------------------------------------
; Calls a VDI function through the runtime's own parameter block.
; Entry: d0.w = opcode, d1.w = intin count, d2.w = ptsin count
; Exit: d0.w = intout[0]
;------------------------------------------------------------------------------
runtime_vdi_call:
	move.w	d0,$642(a6)                     ; contrl[0]
	move.w	d1,$648(a6)                     ; contrl[3]
	move.w	d2,$644(a6)                     ; contrl[1]

runtime_vdi_hide_mouse:
	dc.w	$6100,$0000                     ; bsr.w runtime_vdi_hide_mouse+2 -> Hidem (filled in by the linker),
                                                ;   hide the mouse if shown
	move.l	#runtime_vdi_block_base+2-m_initaes,d1 ; runtime VDI parameter block
	moveq	#115,d0                         ; VDI
	trap	#2                              ; AES/VDI
	move.w	$fa8(a6),d0                     ; intout[0]
	rts

VDI4:
	move.w	d0,$69a(a6)                     ; unlabelled entry: contrl[5] sub-opcode in d0, ptsin count in d3
	move.w	d3,d0                           ; d0 = ptsin count

;------------------------------------------------------------------------------
; VDISYS through the program's VDI block, setting the counts.
; Entry: d0.w = ptsin count, d1.w = opcode, d2.w = intin count
;------------------------------------------------------------------------------
vdi_call_with_counts:
	move.w	d0,$692(a6)                     ; contrl[1]
	move.w	d2,$696(a6)                     ; contrl[3]
	move.w	d1,d0                           ; d0 = opcode

VDI1:
	move.w	d0,$690(a6)                     ; contrl[0]

;------------------------------------------------------------------------------
; VDISYS: calls the VDI with the program's VDI parameter block as it stands.
;------------------------------------------------------------------------------
vdi_call:
	dc.w	$6100,$0000                     ; bsr.w vdi_call+2 -> Hidem (filled in by the linker), hide the mouse if
                                                ;   shown
	move.l	#vdi_user_block_base+2-m_initaes,d1 ; program VDI parameter block
	moveq	#115,d0                         ; VDI
	trap	#2                              ; AES/VDI
	rts

;------------------------------------------------------------------------------
; GEMSYS: calls an AES function through the program's AES parameter block. For opcodes 10-131 control[1-3] come from the
; size table; others use control as the program set it.
; Entry: d0.w = opcode
; Exit: d0-d6 = intout[0-6] (sign-extended), flags from d0
;------------------------------------------------------------------------------
aes_call:
	lea	$684(a6),a1                     ; control[0] = opcode
	move.w	d0,(a1)+
	cmpi.w	#$a,d0                          ; outside the table: control as set
	bcs.s	aes_call_preset                 ; below 10
	cmpi.w	#$83,d0                         ; above 131?
	bhi.s	aes_call_preset
	lea	aes_size_index_base+4(pc),a0    ; entry offsets by opcode
	move.b	0(a0,d0.w),d0                   ; entry offset for the opcode
	lea	aes_array_sizes(pc),a0          ; size table
	adda.w	d0,a0                           ; a0 -> the opcode's entry
	move.b	(a0)+,d0                        ; control[1] = intin count
	move.w	d0,(a1)+
	move.b	(a0)+,d0                        ; intout / addrin counts
	moveq	#15,d1
	and.b	d0,d1                           ; d1 = addrin count
	lsr.b	#4,d0                           ; d0 = intout count
	move.w	d0,(a1)+                        ; control[2]
	move.w	d1,(a1)+                        ; control[3]

;------------------------------------------------------------------------------
; Calls the AES with the program's parameter block, control already filled.
; Exit: d0-d6 = intout[0-6], flags from d0
;------------------------------------------------------------------------------
aes_call_preset:
	dc.w	$6100,$0000                     ; bsr.w aes_call_preset+2 -> QShowm (filled in by the linker), show the
                                                ;   mouse if it should be
	move.l	#aes_user_block-m_initaes,d1    ; program AES parameter block
	move.w	#$c8,d0                         ; AES
	trap	#2                              ; AES/VDI
	movem.w	$11ac(a6),d0-d6                 ; intout[0-6]
	tst.l	d0                              ; flags from intout[0]
	rts

;------------------------------------------------------------------------------
; Turns the runtime block offsets in the four GEM parameter blocks into addresses by adding a6.
;------------------------------------------------------------------------------
relocate_gem_blocks:
	moveq	#21,d0                          ; 22 pointers
	move.l	a6,d1                           ; a6 = the offset base
	lea	aes_user_block(pc),a0           ; first of the blocks
.relocate_loop:
	add.l	d1,(a0)+                        ; offset to address
	dbra	d0,.relocate_loop               ; for every pointer
	rts

;------------------------------------------------------------------------------
; Returns the address of the program's AES parameter block.
; Exit: d0.l -> block
;------------------------------------------------------------------------------
aes_block_address:
	lea	aes_user_block(pc),a0           ; program AES block
	move.l	a0,d0                           ; address as the result
	rts

;------------------------------------------------------------------------------
; Sets conterm bit 3 (Bconin returns the shift state) in supervisor mode.
;------------------------------------------------------------------------------
conterm_shift_on:
	pea	set_conterm_bit(pc)             ; routine to run
	bra.s	supexec_routine                 ; in supervisor mode

;------------------------------------------------------------------------------
; Calls the exit hook (its jsr target is patched when the break handler is installed), then clears conterm bit 3 again
; if the program set it.
;------------------------------------------------------------------------------
restore_keyboard:
	jsr	exit_hook-m_initaes             ; target patched by the break handler set-up
	pea	clear_conterm_bit(pc)           ; routine to run

;------------------------------------------------------------------------------
; Runs the routine whose address was pushed by the caller with Supexec.
;------------------------------------------------------------------------------
supexec_routine:
	move.w	#$26,-(sp)                      ; Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the arguments
	rts

;------------------------------------------------------------------------------
; Supervisor routine: clears conterm bit 3 if the program had set it.
;------------------------------------------------------------------------------
clear_conterm_bit:
	move.b	$0,d0                           ; set by the program?
	beq.s	.done                           ; no: leave it
	bclr	#$3,$484.w                      ; conterm
.done:
	rts

;------------------------------------------------------------------------------
; Supervisor routine: sets conterm bit 3 and records whether it was clear before.
;------------------------------------------------------------------------------
set_conterm_bit:
	bset	#$3,$484.w                      ; conterm
	seq	$0                              ; $ff if the bit was clear

;------------------------------------------------------------------------------
; Empty exit hook; restore_keyboard's jsr to it is redirected when the break handler is installed.
;------------------------------------------------------------------------------
exit_hook:
	rts

; Program AES parameter block (GEMSYS): control, global, intin, intout, addrin, addrout, as runtime block offsets until
; relocate_gem_blocks adds a6.
aes_user_block:
	dc.w	$0000                           ; control
	addi.l	#$666,d4                        ; control (cont.), global
	dc.w	$0000                           ; intin
	move.b	d4,0(a0,d0.w)
	dc.w	$11ac,$0000                     ; intout
	move.b	(a4),$0.w                       ; addrin, addrout

;------------------------------------------------------------------------------
; The program VDI parameter block (VDISYS) starts 2 bytes on: contrl, intin, ptsin, intout, ptsout as
; runtime block offsets until relocate_gem_blocks adds a6.
;------------------------------------------------------------------------------
vdi_user_block_base:
