; COSQ of a float in memory.
; Entry: a0 -> angle in degrees
; Exit: d0-d2 = COSQ((a0)); a0 advanced by 6
;------------------------------------------------------------------------------
VFCOSQ:
	move.l	(a0)+,d0                        ; angle from (a0)
	move.w	(a0)+,d1                        ; low mantissa word
	move.w	(a0)+,d2                        ; exponent word

