	move.w	(a0)+,d1                        ; low mantissa word
	move.w	(a0)+,d2                        ; exponent word

;------------------------------------------------------------------------------
; SINQ(x): quick sine of an angle in degrees, from a table of whole degrees with
; linear interpolation in steps of 1/16 degree.
; Entry: d0-d2 = angle in degrees
; Exit: d0-d2 = sine; d1-d4 used
;------------------------------------------------------------------------------
FSINQ:
	bsr.s	sinq_to_32nds                   ; angle in 1/32 degree

sinq_reduce_angle:
	move.l	#$2d00,d1                       ; 360 degrees
	tst.l	d0
	bpl.s	.check_turn
.add_turn:
	add.l	d1,d0                           ; negative: add whole turns
	bmi.s	.add_turn
	bra.s	.in_range
.subtract_turn:
	sub.l	d1,d0                           ; subtract whole turns
.check_turn:
	cmp.l	d1,d0
	bcc.s	.subtract_turn
.in_range:
	lsr.l	#2,d1                           ; 180 degrees in 1/16 degree
	lsr.l	#1,d0                           ; angle in 1/16 degree, rounded
	bcc.s	.rounded
	addq.l	#1,d0
