	cmp.l	d1,d0                           ; below 180 degrees?
	bcs.s	sinq_half_turn
	sub.l	d1,d0                           ; 180-360: sin(x - 180)
	bsr.s	sinq_half_turn
	neg.w	d2                              ; negated
	rts

;------------------------------------------------------------------------------
; Sine of an angle from 0 to 180 degrees: folds it into 0-90, interpolates in
; sinq_table and turns the 31-bit fraction into a float.
; Entry: d0.l = angle in 1/16 degree, d1.l = 2880 (180 degrees)
