	beq.s	.done                           ; x * 8
	addq.w	#3,d2                           ; x * 8
	move.l	d0,d3                           ; mantissa / 4
	move.w	d1,d4                           ; copy of the mantissa
	lsr.l	#1,d3                           ; shift the copy right twice: x / 4
	roxr.w	#1,d4
	lsr.l	#1,d3
	roxr.w	#1,d4
	addx.w	d4,d1                           ; add: x * 8 * 1.25
	addx.l	d3,d0                           ; x * 8 + x * 2
	bcc.s	.done                           ; no carry: done
	roxr.l	#1,d0                           ; carry: shift down and raise the exponent
	roxr.w	#1,d1
	addq.w	#1,d2
.done:
	rts

