	add.w	d1,d1                           ; x * 2
	addx.l	d0,d0
	move.l	d0,d3                           ; keep x * 2 plus the digit in d3:d4
	add.w	d1,d4                           ; low word plus the digit
	bcc.s	.no_carry                       ; no carry out of the low word
	addq.l	#1,d3                           ; carry into the high long
.no_carry:
	add.w	d1,d1                           ; x * 8
	addx.l	d0,d0                           ; x * 4
	add.w	d1,d1
	addx.l	d0,d0                           ; x * 8
	add.w	d4,d1                           ; x * 8 + x * 2 + digit
	addx.l	d3,d0                           ; plus x * 2 and the carry
	rts

