	lea	$ca(a6),a0                      ; output buffer
	moveq	#32,d3                          ; sign character: space
	tst.w	d2                              ; negative number?
	bge.s	.sign_done                      ; positive
	neg.w	d2                              ; make the exponent positive
	moveq	#45,d3                          ; sign character '-'
.sign_done:
	move.b	d3,(a0)+                        ; store the sign character
	moveq	#0,d6                           ; decimal exponent = 0
	tst.w	d2                              ; exponent 0 means value 0
	beq.w	digits_zero                     ; zero
	cmpi.w	#$1fff,d2                       ; overflow value?
	bhi.s	digits_clamp_large
	cmpi.w	#$3ff,d2                        ; below 1.0?
