	moveq	#0,d1                           ; mantissa low word 0
	moveq	#0,d2                           ; exponent 0
	moveq	#0,d6                           ; d6 = decimal exponent and sign bits
	st	$3d(a6)                         ; overflow sets a flag, not an error
	sf	$3c(a6)                         ; no overflow yet
