                                                ;   mantissa * 10 + digit
	bra.s	val_integer_digits              ; next digit

val_integer_full:
	addq.w	#1,d6                           ; full: only count the exponent
	bra.s	val_integer_digits              ; next digit

val_after_integer:
	cmpi.b	#$2e,d4                         ; decimal point?
	bne.s	val_exponent_letter             ; no: exponent letter?

val_fraction_digits:
	move.b	(a0)+,d4                        ; fraction digits
	cmpi.b	#$30,d4                         ; below '0'?
	bcs.s	val_exponent_letter             ; not a digit
	cmpi.b	#$39,d4                         ; above '9'?
	bhi.s	val_exponent_letter             ; end of the fraction
	cmpi.l	#$fffffff,d0                    ; mantissa full?
	bcc.s	val_fraction_next               ; full: skip the digit

val_call_fvm10_fraction:
