	move.b	(a0)+,d5                        ; next character
	subi.b	#$30,d5                         ; to a value
	cmpi.b	#$9,d5                          ; a digit?
	bhi.s	.exp_done                       ; end of the exponent
	mulu.w	#$a,d4                          ; exponent * 10 + digit
	add.w	d5,d4                           ; + digit
	cmpi.w	#$3e8,d4                        ; exponent over 1000
	ble.s	.exp_digits                     ; up to 1000
	bra.s	val_not_number                  ; is not a number
.exp_done:
	tst.l	d6                              ; negative exponent?
	bpl.s	.exp_add                        ; positive
	neg.w	d4                              ; negative exponent
.exp_add:
	add.w	d4,d6                           ; add to the decimal exponent
.build_float:
	subq.l	#1,a0                           ; point at the terminator
	move.w	#$42e,d2                        ; exponent for a 48-bit integer

