val_scale_up_loop:
	dc.w	$6100,$0000                     ; bsr.w val_scale_up_loop+2 -> Fmul10 (filled in by the linker), times
                                                ;   10 per decimal place
	dbra	d6,val_scale_up_loop            ; for each decimal place

val_call_fnorm_scaled:
	dc.w	$6100,$0000                     ; bsr.w val_call_fnorm_scaled+2 -> Fnorm (filled in by the linker),
                                                ;   normalise
	bra.s	val_apply_sign

val_scale_down:
	movem.l	d0-d2,-(sp)                     ; build 10^-exponent

val_call_feins:
	dc.w	$6100,$0000                     ; bsr.w val_call_feins+2 -> Feins (filled in by the linker), start at
                                                ;   1.0
	not.w	d6                              ; d6 = -exponent - 1 for dbra

val_power_loop:
