	move.w	d1,d4
	move.l	d2,d5
	movem.l	(sp)+,d0-d2                     ; value back
	move.l	d6,-(sp)                        ; keep the sign bits

val_call_fdiv:
	dc.w	$6100,$0000                     ; bsr.w	val_call_fdiv+2 -> FDIV (filled in by the linker), value / 10^n
