;------------------------------------------------------------------------------
; ARRAYFILL of a float array: every 8-byte element set to the float.
; Entry: a0 = array descriptor, d0-d2 = value
;------------------------------------------------------------------------------
array_fill_floats:
	move.l	d0,d4                           ; float array fill: 8 bytes per element
	move.w	d1,d5                           ; low mantissa word
	swap	d5
	move.w	d2,d5                           ; exponent: d4/d5 = the 8-byte element
	bsr.w	array_element_count             ; element count
	asl.l	#3,d0                           ; times 8 bytes
	bra.s	fill_bytes_pattern              ; fill

;------------------------------------------------------------------------------
; Fills a flag (bit) array with all set or all clear bits, rounding the element count up to whole words.
; Entry: a0 = array descriptor, d0 = value (non-zero sets every flag).
; Exit: array filled; d0-d5/a1 used.
;------------------------------------------------------------------------------
array_fill_flags:
