	movea.l	d6,a2                           ; a2 = buttons
	lea	$4a(a6),a0                      ; build in the text buffer
	moveq	#3,d0                           ; icon 0-3
	and.w	(sp)+,d0                        ; d0 = icon number
	ori.w	#$5b30,d0                       ; "[n"
	move.w	d0,(a0)+                        ; store "[n"
	move.w	#$5d5b,(a0)+                    ; "]["
	moveq	#3,d3                           ; at most 5 lines
	moveq	#30,d4                          ; of 30 characters
	bra.s	.text_next                      ; into the text loop
.text_char:
	move.b	(a1)+,d0                        ; next text character
	cmpi.b	#$5b,d0                         ; brackets are left out
	beq.s	.text_next                      ; '[': skip it
	cmpi.b	#$5d,d0                         ; ']'?
	beq.s	.text_next                      ; yes: skip it
	move.b	d0,(a0)+                        ; store the character
	cmpi.b	#$7c,d0                         ; '|' starts a new line
	beq.s	.text_new_line                  ; yes: start a new line
	dbra	d4,.text_next                   ; line still has room?
	subq.l	#1,a0                           ; full: drop the character
	moveq	#0,d4                           ; nothing more fits on this line
	bra.s	.text_next
.text_new_line:
	moveq	#30,d4                          ; new line
	dbra	d3,.text_next                   ; too many lines?
	subq.l	#1,a0                           ; drop the '|' and stop
	moveq	#0,d1                           ; end the text loop
.text_next:
	dbra	d1,.text_char                   ; next text character
	move.b	#$5d,(a0)+                      ; "]["
	move.b	#$5b,(a0)+                      ; "[" of the buttons part
	moveq	#2,d3                           ; at most 3 buttons
	moveq	#8,d4                           ; of 8 characters
	bra.s	.button_next                    ; into the button loop
.button_char:
	move.b	(a2)+,d0                        ; next button character
	cmpi.b	#$5b,d0                         ; brackets are left out
	beq.s	.button_next                    ; '[': skip it
	cmpi.b	#$5d,d0                         ; ']'?
	beq.s	.button_next                    ; yes: skip it
	move.b	d0,(a0)+                        ; store the character
	cmpi.b	#$7c,d0                         ; '|' starts a new button
	beq.s	.button_new                     ; yes: start a new button
	dbra	d4,.button_next                 ; button still has room?
	subq.l	#1,a0                           ; full: drop the character
	moveq	#0,d4                           ; nothing more fits in this button
	bra.s	.button_next
.button_new:
	moveq	#8,d4                           ; new button
	dbra	d3,.button_next                 ; too many buttons?
	subq.l	#1,a0                           ; drop the '|' and stop
	moveq	#0,d2                           ; end the button loop
.button_next:
