;------------------------------------------------------------------------------
decrement_float_in_place:
	move.l	(a0)+,d0                        ; decrement a float in memory
	move.w	(a0)+,d1                        ; mantissa low
	move.w	(a0)+,d2                        ; exponent
	neg.w	d2                              ; negate
