; Exit: d0/d1/d2 = float - 1.
;------------------------------------------------------------------------------
float_decrement:
	neg.w	d2                              ; negate
	bsr.s	float_increment                 ; add 1
	neg.w	d2                              ; negate back
	rts

;------------------------------------------------------------------------------
; Loads a float from memory and adds 1.
; Entry: a0 -> float
; Exit: d0-d2 = (a0) + 1
;------------------------------------------------------------------------------
