;------------------------------------------------------------------------------
; MENU KILL: turns off all the ON MENU handlers and removes the menu bar.
; Entry: a6 = runtime variables.
; Exit: d0-d1/a0 changed.
;------------------------------------------------------------------------------
MENUKILL:
	lea	$1334(a6),a0                    ; ON MENU handler addresses
	moveq	#5,d0                           ; 7 handler longs
.clear_handlers:
	clr.l	(a0)+                           ; clear one
	dbra	d0,.clear_handlers              ; for all of them
	clr.w	(a0)+                           ; and the event mask word after them

;------------------------------------------------------------------------------
; Removes the menu bar if there is one: MENU_BAR(tree,0) and forgets the tree.
; Exit: d0-d1 changed.
;------------------------------------------------------------------------------
menu_remove_bar:
	move.l	$12a0(a6),d1                    ; menu tree
	beq.s	menu_remove_return              ; none
	moveq	#0,d0                           ; 0 = remove the bar

menu_call_menu_bar_off:
	dc.w	$6100,$0000                     ; bsr.w menu_call_menu_bar_off+2 -> MENU_BAR (filled in by the linker),
                                                ;   menu_bar(tree,0)
	clr.l	$12a0(a6)                       ; no menu tree

menu_remove_return:
	rts

; Character height in pixels from graf_handle, used for the entry rows.
menu_char_height:
	dc.w	$0000                           ; character height

;------------------------------------------------------------------------------
; Builds the fixed part of the menu tree in the module's 200-object tree: objects 1-200
; chained as empty G_STRINGs one character high, the root (0, G_IBOX, the desktop work
; area width, 25 lines high), the bar (1, G_BOX), the title box (2, G_IBOX from x 16),
; the titles 3-20 (G_TITLE) and the drop-down parent (21, G_IBOX at the desktop corner).
; Exit: a2 = ob_tail of object 21; d0-d2/a0 changed; desktop work area at $1258(a6).
