	move.l	d1,(a0)+                        ; no children
	move.w	#$1c,(a0)+                      ; ob_type = G_STRING
	clr.l	(a0)+                           ; ob_flags, ob_state = 0
	clr.l	(a0)+                           ; ob_spec = 0
	clr.l	(a0)+                           ; ob_x, ob_y = 0
	move.l	d2,(a0)+                        ; ob_width, ob_height: one character high
	addq.w	#1,d0                           ; next object number
	cmpi.w	#$c9,d0                         ; 200 objects
	bne.s	.init_object
	lea	$0,a0                           ; object 0: the root
	move.w	d1,(a0)+                        ; ob_next = -1
	move.w	#$1,(a0)+                       ; ob_head = 1
	move.w	#$15,(a0)+                      ; ob_tail = 21
	move.w	#$19,(a0)+                      ; ob_type = G_IBOX
	addq.l	#8,a0                           ; skip flags, state, spec
