;------------------------------------------------------------------------------
; MENU m$(): builds a menu bar from a one-dimensional string array and shows it. Each menu
; is a title followed by its entries and ends with an empty string; a second empty string
; ends the bar. Entries starting with '-' are disabled. At most 18 titles and 200 objects
; with 4000 bytes of text.
; Entry: a0 = array descriptor.
; Exit: error 28 for an array that is not one-dimensional, error 62 when the menu is too big.
;------------------------------------------------------------------------------
MENU:
	movem.l	a3/a5,$4a(a6)                   ; keep a3/a5 in the text buffer
	bsr.s	menu_build                      ; build the menu

menu_restore_regs:
	movem.l	$4a(a6),a3/a5                   ; restore a3/a5
	rts

;------------------------------------------------------------------------------
; Takes the next string of the array, counting down the element count the caller keeps on
; the stack.
; Entry: a3 = next descriptor, 4(sp) = elements left.
; Exit: a0 = string address, d0.w = length; Z set for an empty string or the end of the array.
;------------------------------------------------------------------------------
menu_next_string:
	subq.l	#1,4(sp)                        ; one element fewer
	bmi.s	.end_of_array                   ; none left
	movea.l	(a3)+,a0                        ; string address
	move.w	(a3)+,d0                        ; length
	rts
.end_of_array:
	moveq	#0,d0                           ; as an empty string
	rts

menu_error_dimensions:
	moveq	#28,d0                          ; error 28

menu_error:
	bsr.s	menu_restore_regs               ; restore a3/a5

menu_call_error:
	dc.w	$6000,$0000                     ; bra.w menu_call_error+2 -> ERROR (filled in by the linker), stop with
                                                ;   the error

menu_error_too_big:
	moveq	#62,d0                          ; error 62
	bra.s	menu_error

;------------------------------------------------------------------------------
; Builds the menu tree from the array and shows the bar (body of MENU).
; Entry: a0 = array descriptor.
; Uses d1-d7/a0-a2/a5 (a3/a5 saved by the caller).
