menu_build:
	pea	(a0)                            ; keep the descriptor
	bsr.w	menu_remove_bar                 ; remove the old bar
	bsr.w	menu_build_skeleton             ; build the fixed objects
	movea.l	(sp)+,a0                        ; the descriptor
	movea.l	(a0)+,a3                        ; a3 = the array's data
	cmpi.w	#$1,(a0)                        ; one dimension?
	bne.s	menu_error_dimensions           ; no: error
	move.l	(a3)+,-(sp)                     ; element count, counted down by menu_next_string
	moveq	#3,d6                           ; d6 = title object, from 3
	moveq	#22,d7                          ; d7 = next free object, from 22
	lea	$12c0,a5                        ; a5 = the module's text area
	moveq	#0,d5                           ; d5 = x of the next title
.next_title:
