	beq.w	menu_finish                     ; empty: end of the bar
	cmpi.w	#$a,d0                          ; more than 10 characters?
	bcs.s	.title_length                   ; no
	moveq	#10,d0                          ; cut to 10
.title_length:
	move.w	d0,d1                           ; d1 = title length
	moveq	#24,d2                          ; offset of the title object
	mulu.w	d6,d2
	lea	$c,a1                           ; address error vector, the module's tree + ob_spec
	adda.l	d2,a1                           ; a1 = ob_spec of the title
	move.l	a5,(a1)+                        ; ob_spec = the text
	move.w	d5,(a1)+                        ; ob_x
	move.b	#$20,(a5)+                      ; leading space
	subq.w	#1,d0                           ; dbra count
	pea	(a1)                            ; keep a1 (at ob_y)
	lea	$2260,a1                        ; end of the text area
.copy_title:
	move.b	(a0)+,(a5)+                     ; copy a character
	cmpa.l	a1,a5                           ; text area full?
	dbhi	d0,.copy_title                  ; no: next character
	movea.l	(sp)+,a1                        ; a1 = ob_y
	bcc.w	menu_too_big                    ; text area full: error 62
	move.b	#$20,(a5)+                      ; trailing space
	clr.b	(a5)+                           ; zero terminate
	addq.w	#2,d1                           ; + 2 spaces
	asl.w	#3,d1                           ; * 8 pixels
	move.w	d1,2(a1)                        ; ob_width of the title
	moveq	#24,d0                          ; drop-down box object
	mulu.w	d7,d0                           ; offset
	lea	$0,a1                           ; the module's tree
	adda.l	d0,a1                           ; a1 = the box
