.copy_entry:
	pea	(a1)                            ; keep a1
	lea	$2260,a1                        ; end of the text area
.copy_char:
	move.b	(a0)+,(a5)+                     ; copy a character
	cmpa.l	a1,a5                           ; text area full?
	dbhi	d0,.copy_char                   ; no: next character
	movea.l	(sp)+,a1                        ; restore a1
	bcc.s	menu_too_big                    ; full: error 62
	clr.b	(a5)+                           ; zero terminate
	asl.w	#3,d1                           ; width in pixels
	cmp.w	d1,d4                           ; widest so far?
	bhi.s	.next_object                    ; no
	move.w	d1,d4                           ; yes: keep it
.next_object:
	adda.w	#$18,a1                         ; next object
	addq.w	#1,d7                           ; its number
	addq.w	#1,d3                           ; one entry more
	bra.s	.next_entry                     ; next entry
