	adda.w	#$18,a0                         ; next object
	cmpa.l	a1,a0                           ; up to the last entry
	bls.s	.set_width
	bsr.s	menu_next_object                ; count the box's object, error 62 past 199
	addq.w	#1,d6                           ; next title
	cmpi.w	#$15,d6                         ; up to object 20
	bcs.w	.next_title                     ; next menu

menu_too_big:
	bra.w	menu_error_too_big              ; error 62

;------------------------------------------------------------------------------
; Counts one more object and stops with error 62 past object 199.
; Entry: d7 = object number.
; Exit: d7 + 1.
;------------------------------------------------------------------------------
