	move.w	d4,d0                           ; y2 as the last parameter

windows_call_clipxyxy:
	dc.w	$6000,$0000                     ; bra.w windows_call_clipxyxy+2 -> CLIPXYXY (filled in by the linker),
                                                ;   clip and return

;------------------------------------------------------------------------------
; TOPW n: tops BASIC window n and makes it the output window.
; Entry: d0.w = n.
;------------------------------------------------------------------------------
TOPW:
	subq.w	#1,d0                           ; window number - 1
	bmi.s	.done                           ; 0: nothing
	andi.w	#$3,d0                          ; windows 1-4
	mulu.w	#$c,d0                          ; 12 bytes per window
	lea	$1224(a6),a0                    ; window table
	move.w	0(a0,d0.l),$10e4(a6)            ; int_in[0] = handle
	bne.s	windows_top                     ; open: top it
.done:
	rts

;------------------------------------------------------------------------------
; Closes all four BASIC windows and sets them up again (end of program, CLOSEW 0 ...).
; Exit: d0-d7/a0 changed.
;------------------------------------------------------------------------------
Killws:
	moveq	#3,d0                           ; windows 4 to 1
.close_next:
	move.w	d0,-(sp)                        ; keep the index
	bsr.s	windows_close_index             ; close it
	move.w	(sp)+,d0                        ; the index
	dbra	d0,.close_next                  ; all four
	movem.w	$128c(a6),d1-d4                 ; clipping rectangle
	bsr.s	windows_set_origin_clip         ; origin and clip
	bra.w	WINDINIT                        ; set the windows up again

;------------------------------------------------------------------------------
; CLOSEW n: closes BASIC window n and makes the new top window the output window, or the
; screen when none is left; n = 0 only switches output to the screen.
; Entry: d0.w = n.
;------------------------------------------------------------------------------
CLOSEW:
	subq.w	#1,d0                           ; window number - 1
	bmi.s	windows_output_screen           ; 0: back to the screen
	andi.w	#$3,d0                          ; windows 1-4

;------------------------------------------------------------------------------
; Closes the BASIC window with table index d0 (0-3) if it is open.
; Entry: d0.w = index.
;------------------------------------------------------------------------------
windows_close_index:
	mulu.w	#$c,d0                          ; 12 bytes per window
	lea	$1224(a6),a0                    ; window table
	adda.l	d0,a0                           ; this window
	move.w	(a0),d0                         ; handle
	beq.s	windows_find_top                ; not open
	clr.w	(a0)                            ; forget the handle
	move.w	d0,$10e4(a6)                    ; int_in[0] = handle

windows_call_wind_close:
	dc.w	$6100,$0000                     ; bsr.w windows_call_wind_close+2 -> WIND_CLO (filled in by the linker),
                                                ;   wind_close
	moveq	#103,d0                         ; wind_delete

windows_call_wind_delete:
	dc.w	$6100,$0000                     ; bsr.w windows_call_wind_delete+2 -> Xaes (filled in by the linker),
                                                ;   call it

windows_find_top:
	moveq	#10,d0                          ; WF_TOP

windows_call_wind_get_top:
	dc.w	$6100,$0000                     ; bsr.w windows_call_wind_get_top+2 -> WIND_GET (filled in by the
                                                ;   linker), d0 = top window handle
	tst.w	d0                              ; any?
	bne.w	windows_use_handle              ; yes: make it the output window

windows_output_screen:
	moveq	#0,d0                           ; desktop work area
	bsr.w	windows_use_handle              ; origin and clip
	sf	$1268(a6)                       ; window output off
	movem.w	$12a4(a6),d0-d1                 ; screen size - 1
	addq.w	#1,d0                           ; width
	addq.w	#1,d1                           ; height
	movem.w	d0-d1,$168(a6)                  ; graphic window size = the screen
	clr.l	$1264(a6)                       ; origin 0,0
	movem.w	$128c(a6),d1-d4                 ; clipping rectangle
	moveq	#0,d1                           ; from 0,0
	moveq	#0,d2
	bra.w	windows_set_clip_xyxy           ; to the screen's x2, y2
	rts                                     ; not reached

;------------------------------------------------------------------------------
; Writes text into the output window (PRINT with windows open). Characters are drawn with
; v_gtext in character cells from the cursor column and row; with d6 = 2 CR, LF, BS, BEL,
; ESC E (clear window) and ESC p / ESC q (text effect bit 3 on / off) are obeyed, other
; control codes ignored; otherwise every byte is drawn. A full window scrolls up.
; Entry: a1 = text, d0.l = byte count, d6.w = output mode.
; Exit: d0-d7/a0-a1 changed.
;------------------------------------------------------------------------------
Wprsub:
	pea	(a3)                            ; keep a3
	movea.l	a1,a3                           ; a3 = text
	move.l	d0,d7                           ; d7 = count (high word for dbra)
	cmpi.w	#$2,d6                          ; mode 2?
	sne	$1269(a6)                       ; no: draw every byte
	move.w	$129c(a6),d4                    ; d4 = character cell width
	move.w	$129e(a6),d5                    ; d5 = character cell height
	movem.w	$1288(a6),d0-d1                 ; window width, height
	move.w	$1294(a6),d2                    ; cursor column
	addq.w	#1,d2                           ; + 1
	mulu.w	d4,d2                           ; * cell width
	cmp.w	d0,d2                           ; past the right edge?
	bls.s	.check_row                      ; no
	clr.w	$1294(a6)                       ; column 0
	bsr.w	windows_newline                 ; next line
	movem.w	$1288(a6),d0-d1                 ; width, height again
.check_row:
	move.w	$1296(a6),d2                    ; cursor row
	addq.w	#1,d2                           ; + 1
	mulu.w	d5,d2                           ; * cell height
	cmp.w	d1,d2                           ; past the bottom?
	bls.s	windows_print_skip              ; no
	divu.w	d5,d1                           ; rows that fit
	subq.w	#1,d1                           ; last row
	move.w	d1,$1296(a6)                    ; cursor row
	bra.s	windows_print_skip              ; start

windows_print_next:
	moveq	#0,d0                           ; next byte
	move.b	(a3)+,d0
	tst.b	$1269(a6)                       ; draw every byte?
	bne.s	windows_print_char              ; yes
	tas	$1298(a6)                       ; escape pending? (clears the flag)
	bmi.s	windows_print_control           ; no: ordinary byte
	cmpi.b	#$45,d0                         ; ESC E?
	beq.s	windows_print_clear             ; yes: clear the window
	move.w	$129a(a6),d1                    ; current text effects
	bset	#$3,d1                          ; bit 3 on
	cmpi.b	#$70,d0                         ; ESC p?
	beq.s	.set_effects                    ; yes
	bclr	#$3,d1                          ; bit 3 off
	cmpi.b	#$71,d0                         ; ESC q?
	bne.s	windows_print_continue          ; other: ignored
.set_effects:
	move.w	d1,$129a(a6)                    ; keep the effects
	move.w	d1,$6a8(a6)                     ; intin[0]
	moveq	#106,d0                         ; vst_effects
	moveq	#1,d1                           ; one intin word
	moveq	#0,d2                           ; no ptsin

windows_call_vst_effects:
	dc.w	$6100,$0000                     ; bsr.w windows_call_vst_effects+2 -> Xvdi (filled in by the linker),
                                                ;   set the effects

windows_print_skip:
	bra.s	windows_print_continue          ; next byte

windows_print_clear:
	bsr.w	windows_clear_window            ; ESC E: clear the window, cursor home
	bra.s	windows_print_continue          ; next byte

windows_print_control:
	cmpi.b	#$20,d0                         ; printable?
	bcc.s	windows_print_char              ; yes: draw it
	cmpi.b	#$1b,d0                         ; ESC?
	sne	$1298(a6)                       ; flag 0 = escape pending
	beq.s	windows_print_continue          ; yes: next byte
	cmpi.b	#$d,d0                          ; CR?
	beq.s	windows_print_cr                ; yes
	cmpi.b	#$a,d0                          ; LF?
	beq.s	windows_print_newline           ; yes
	cmpi.b	#$7,d0                          ; BEL?
	beq.s	windows_print_bell              ; yes
	cmpi.b	#$8,d0                          ; BS?
	bne.s	windows_print_loop              ; other: ignored
	subq.w	#1,$1294(a6)                    ; one column back
	bpl.s	windows_print_continue          ; still on the line
	clr.w	$1294(a6)                       ; column 0

windows_print_continue:
	bra.s	windows_print_loop              ; next byte

windows_print_char:
	move.w	d0,$6a8(a6)                     ; intin[0] = character
	move.w	$1294(a6),d0                    ; cursor column
	mulu.w	d4,d0                           ; * cell width
	add.w	$1264(a6),d0                    ; + origin x
	move.w	d0,$7a8(a6)                     ; ptsin x
	move.w	$1296(a6),d0                    ; cursor row
	addq.w	#1,d0                           ; + 1
	mulu.w	d5,d0                           ; * cell height
	subq.w	#1,d0                           ; - 1: baseline
	add.w	$1266(a6),d0                    ; + origin y
	move.w	d0,$7aa(a6)                     ; ptsin y
	moveq	#8,d0                           ; v_gtext
	moveq	#1,d1                           ; one character
	moveq	#1,d2                           ; one point

windows_call_v_gtext:
	dc.w	$6100,$0000                     ; bsr.w windows_call_v_gtext+2 -> Xvdi (filled in by the linker), draw
                                                ;   it
	addq.w	#1,$1294(a6)                    ; next column
	move.w	d4,d0                           ; cell width
	mulu.w	$1294(a6),d0                    ; * column
	cmp.w	$1288(a6),d0                    ; still inside the window?
	bcs.s	windows_print_loop              ; yes
	clr.w	$1294(a6)                       ; column 0

windows_print_newline:
	bsr.s	windows_newline                 ; next line

windows_print_loop:
	dbra	d7,windows_print_next           ; count the byte
	subi.l	#$10000,d7                      ; high word of the count
	bpl.w	windows_print_next              ; more bytes
	movea.l	(sp)+,a3                        ; restore a3
	rts

windows_print_cr:
	clr.w	$1294(a6)                       ; CR: column 0
	bra.s	windows_print_loop              ; next byte

windows_print_bell:
	move.w	#$7,-(sp)                       ; BEL
	pea	$30002                          ; Bconout(2 = console, 7)
	trap	#13                             ; BIOS, BIOS
	addq.l	#6,sp                           ; drop the parameters
	bra.s	windows_print_loop              ; next byte

;------------------------------------------------------------------------------
; Moves the cursor to the next row, scrolling the window up by a row when it is the last.
; Entry: d5 = cell height.
; Exit: d6 changed.
;------------------------------------------------------------------------------
windows_newline:
	addq.w	#1,$1296(a6)                    ; next row
	move.w	d5,d6                           ; cell height
	mulu.w	$1296(a6),d6                    ; * row
	subq.w	#1,d6                           ; - 1
	add.w	d5,d6                           ; + one more row
	sub.w	$128a(a6),d6                    ; past the window bottom?
	bcs.s	.done                           ; no: done
	subq.w	#1,$1296(a6)                    ; stay on the last row
	bra.w	windows_scroll                  ; scroll up
.done:
	rts

;------------------------------------------------------------------------------
; CLEARW n (without topping): clears every visible rectangle of BASIC window n from the
; AES rectangle list (WF_FIRSTXYWH / WF_NEXTXYWH) inside wind_update.
; Entry: d0.w = n.
;------------------------------------------------------------------------------
NCLEARW:
	subq.w	#1,d0                           ; window number - 1
	bmi.s	windows_clear_return            ; 0: nothing
	andi.w	#$3,d0                          ; windows 1-4
	mulu.w	#$c,d0                          ; 12 bytes per window
	lea	$1224(a6),a0                    ; window table
	adda.l	d0,a0                           ; this window
	lea	$10e4(a6),a1                    ; AES int_in
	move.w	(a0),d0                         ; handle
	beq.s	windows_clear_return            ; not open
	move.w	d0,-(sp)                        ; keep the handle
	bsr.s	windows_begin_update            ; wind_update BEG_UPDATE
	move.w	(sp)+,$10e4(a6)                 ; handle to int_in[0]
	moveq	#11,d0                          ; WF_FIRSTXYWH

windows_clear_next_rect:
	move.w	$10e4(a6),d1                    ; handle

windows_call_wind_get_rect:
	dc.w	$6100,$0000                     ; bsr.w windows_call_wind_get_rect+2 -> WIND_GET (filled in by the
                                                ;   linker), rectangle of the list
	movem.w	$11ae(a6),d4-d7                 ; x, y, w, h
	move.w	d7,d3                           ; h
	or.w	d6,d3                           ; or w
	beq.s	.end_update                     ; empty: end of the list
	bsr.s	windows_clear_rect              ; clear it
	moveq	#12,d0                          ; WF_NEXTXYWH
	bra.s	windows_clear_next_rect         ; next rectangle
.end_update:
	moveq	#0,d0                           ; END_UPDATE
	bra.s	windows_call_wind_update        ; end the update

;------------------------------------------------------------------------------
; wind_update(1): BEG_UPDATE.
;------------------------------------------------------------------------------
windows_begin_update:
	moveq	#1,d0                           ; BEG_UPDATE

windows_call_wind_update:
	dc.w	$6000,$0000                     ; bra.w windows_call_wind_update+2 -> WIND_UPD (filled in by the
                                                ;   linker), wind_update and return

windows_clear_return:
	rts

;------------------------------------------------------------------------------
; CLEARW n: tops BASIC window n, makes it the output window, homes the cursor and clears
; its work area (the first rectangle of the list).
; Entry: d0.w = n (0 = clear the whole screen).
;------------------------------------------------------------------------------
CLEARW:
	clr.l	$1294(a6)                       ; cursor column and row 0
	subq.w	#1,d0                           ; window number - 1
	bmi.s	windows_clear_rect_return       ; 0: nothing
	andi.w	#$3,d0                          ; windows 1-4
	mulu.w	#$c,d0                          ; 12 bytes per window
	lea	$1224(a6),a0                    ; window table
	adda.l	d0,a0                           ; this window
	move.w	(a0),$10e4(a6)                  ; int_in[0] = handle
	bsr.w	windows_top                     ; top it and make it the output window
	move.w	#$b,$10e6(a6)                   ; WF_FIRSTXYWH
	moveq	#104,d0                         ; wind_get

windows_call_wind_get_first:
	dc.w	$6100,$0000                     ; bsr.w windows_call_wind_get_first+2 -> Xaes (filled in by the linker),
                                                ;   first visible rectangle
	movem.w	$110e(a6),d4-d7                 ; x, y, w, h from int_out
	bra.s	windows_clear_rect              ; clear it and return

;------------------------------------------------------------------------------
; Clears the output window (ESC E): cursor home, then vro_cpyfm mode 0 (all white) over the
; whole screen MFDB, limited by the clipping rectangle.
; Exit: through Xvdi.
;------------------------------------------------------------------------------
windows_clear_window:
	moveq	#0,d0
	move.l	d0,$1294(a6)                    ; cursor column and row 0
	move.l	#$7fff7fff,d1                   ; 32767, 32767
	move.l	d0,d2                           ; source 0,0
	move.l	d1,d3                           ; to 32767,32767
	movem.l	d0-d3,$7a8(a6)                  ; ptsin: source and target rectangles
	lea	windows_screen_mfdb(pc),a0      ; screen MFDB
	move.l	a0,$650(a6)                     ; contrl[7..8] = source MFDB
	move.l	a0,$654(a6)                     ; contrl[9..10] = target MFDB
	clr.w	$6a8(a6)                        ; intin[0] = mode 0: all white
	moveq	#109,d0                         ; vro_cpyfm
	moveq	#1,d1                           ; one intin word
	moveq	#4,d2                           ; four points

windows_call_vro_cpyfm:
	dc.w	$6000,$0000                     ; bra.w windows_call_vro_cpyfm+2 -> Xvdi (filled in by the linker),
                                                ;   clear and return

; MFDB address 0: the screen.
windows_screen_mfdb:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Clears a screen rectangle with the Line-A BitBlt (mode 0) in supervisor mode, the mouse
; hidden.
; Entry: d4-d7 = x, y, w, h.
; Exit: d0-d3/a0 changed.
;------------------------------------------------------------------------------
windows_clear_rect:
	pea	windows_clear_rect_super(pc)    ; routine for Supexec
	dc.w	$a00a                           ; Line-A Hide mouse, hide the mouse
	move.w	#$26,-(sp)                      ; Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the parameters

windows_clear_rect_return:
	rts

;------------------------------------------------------------------------------
; Supervisor part of windows_clear_rect: blits the rectangle onto itself with all
; op_tab entries 0.
; Entry: d4-d7 = x, y, w, h.
;------------------------------------------------------------------------------
windows_clear_rect_super:
	movea.l	$34(a6),a0                      ; Line-A variables
	lea	$7a8(a6),a6                     ; a6 = BitBlt block (ptsin area)
	tst.w	d6                              ; no width?
	ble.s	.done                           ; yes: nothing to clear
	tst.w	d7                              ; no height?
	ble.s	.done                           ; yes: nothing to clear
	movem.w	d6-d7,(a6)                      ; b_wd, b_ht
	move.l	$44e.w,d0                       ; _v_bas_ad, _v_bas_ad: screen address
	move.l	d0,$12(a6)                      ; s_form
	move.l	d0,$20(a6)                      ; d_form
	moveq	#0,d0
	move.l	d0,$2a(a6)                      ; p_addr = 0: no pattern
	move.l	d0,6(a6)                        ; fg_col, bg_col = 0
	move.l	d0,$a(a6)                       ; op_tab = 0: clear
	movem.w	d4-d5,$e(a6)                    ; s_xmin, s_ymin
	movem.w	d4-d5,$1c(a6)                   ; d_xmin, d_ymin
	move.w	-$c(a0),d0                      ; V_REZ_HZ
	movem.w	-$4(a0),d1-d3                   ; V_REZ_VT, BYTES_LIN, PLANES
	move.w	d2,$18(a6)                      ; s_nxln
	move.w	d2,$26(a6)                      ; d_nxln
	move.w	d3,4(a6)                        ; plane_ct
	add.w	d3,d3                           ; 2 bytes per plane
	move.w	d3,$16(a6)                      ; s_nxwd
	move.w	d3,$24(a6)                      ; d_nxwd
	moveq	#2,d2                           ; offset between planes: 2
	cmp.w	d2,d3                           ; one plane?
	bne.s	.store_nxpl                     ; no
	moveq	#0,d2                           ; mono: 0
.store_nxpl:
	move.w	d2,$1a(a6)                      ; s_nxpl
	move.w	d2,$28(a6)                      ; d_nxpl
	dc.w	$a007                           ; Line-A Bit block transfer, clear
.done:
	rts

;------------------------------------------------------------------------------
; Scrolls the clipping rectangle up by one character row and clears the row at the bottom,
; with the Line-A BitBlt in supervisor mode, the mouse hidden.
; Entry: d5 = cell height.
;------------------------------------------------------------------------------
windows_scroll:
	dc.w	$6100,$0000                     ; bsr.w windows_scroll+2 -> Hidem (filled in by the linker), hide the
                                                ;   mouse
	pea	windows_scroll_super(pc)        ; routine for Supexec
	move.w	#$26,-(sp)                      ; Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the parameters
	rts

windows_scroll_super:
	movem.w	$128c(a6),d0-d3                 ; clip x1, y1, x2, y2
	movea.l	$34(a6),a0                      ; Line-A variables
	lea	$7a8(a6),a6                     ; a6 = BitBlt block (ptsin area)
	move.l	$44e.w,d4                       ; _v_bas_ad, _v_bas_ad: screen address
	move.l	d4,$12(a6)                      ; s_form
	move.l	d4,$20(a6)                      ; d_form
	moveq	#0,d4
	move.l	d4,$2a(a6)                      ; p_addr = 0: no pattern
	move.l	d4,6(a6)                        ; fg_col, bg_col = 0
	move.b	#$3,$a(a6)                      ; op_tab: replace
	tst.w	d0                              ; x1 negative?
	bpl.s	.clip_y1                        ; no
	moveq	#0,d0                           ; clip to 0
.clip_y1:
	tst.w	d1                              ; y1 negative?
	bpl.s	.clip_x2                        ; no
	moveq	#0,d1                           ; clip to 0
.clip_x2:
	addq.w	#1,d2                           ; right edge + 1
	cmp.w	-$c(a0),d2                      ; inside the screen width?
	bcs.s	.clip_y2                        ; yes
	move.w	-$c(a0),d2                      ; clip to it
.clip_y2:
	addq.w	#1,d3                           ; bottom edge + 1
	cmp.w	-$4(a0),d3                      ; inside the screen height?
	bcs.s	.size                           ; yes
	move.w	-$4(a0),d3                      ; clip to it
.size:
	sub.w	d0,d2                           ; width
	ble.s	.done                           ; nothing left
	sub.w	d1,d3                           ; height
	ble.s	.done                           ; nothing left
	move.w	d0,$e(a6)                       ; s_xmin
	move.w	d0,$1c(a6)                      ; d_xmin
	move.w	d2,(a6)                         ; b_wd
	sub.w	d5,d3                           ; height less one row
	move.w	d3,2(a6)                        ; b_ht
	move.w	d1,$1e(a6)                      ; d_ymin = y1
	add.w	d5,d1                           ; one row lower
	move.w	d1,$10(a6)                      ; s_ymin
	move.w	-$2(a0),d2                      ; BYTES_LIN
	move.w	d2,$18(a6)                      ; s_nxln
	move.w	d2,$26(a6)                      ; d_nxln
	move.w	(a0),d3                         ; PLANES
	move.w	d3,4(a6)                        ; plane_ct
	move.w	d3,-(sp)                        ; keep it
	add.w	d3,d3                           ; 2 bytes per plane
	move.w	d3,$16(a6)                      ; s_nxwd
	move.w	d3,$24(a6)                      ; d_nxwd
	moveq	#2,d2                           ; offset between planes: 2
	cmp.w	d2,d3                           ; one plane?
	bne.s	.store_nxpl                     ; no
	moveq	#0,d2                           ; mono: 0
.store_nxpl:
	move.w	d2,$1a(a6)                      ; s_nxpl
	move.w	d2,$28(a6)                      ; d_nxpl
	movea.l	a6,a5                           ; the BitBlt changes a6
	dc.w	$a007                           ; Line-A Bit block transfer, move the rows up
	movea.l	a5,a6                           ; block pointer back
	move.w	(sp)+,4(a6)                     ; plane_ct again
	clr.l	6(a6)                           ; fg_col, bg_col = 0
	clr.w	$a(a6)                          ; op_tab = 0: clear
	move.w	$1e(a6),d0                      ; y1
	add.w	2(a6),d0                        ; + rows moved
	move.w	d0,$10(a6)                      ; s_ymin of the last row
	move.w	d0,$1e(a6)                      ; d_ymin
	move.w	d5,2(a6)                        ; b_ht = one row
	dc.w	$a007                           ; Line-A Bit block transfer, clear the last row
.done:
	rts

