;------------------------------------------------------------------------------
MODE:
	lsr.w	#1,d0                           ; bit 0: US date order
	scs	$61c(a6)                        ; US date flag
	move.w	#$2e2c,d1                       ; "." and ","
	lsr.w	#1,d0                           ; bit 1: swap them
	bcc.s	.store_separators               ; no
	ror.w	#8,d1                           ; "," and "."
.store_separators:
	move.w	d1,$61e(a6)                     ; decimal point and thousands separator
	rts

;------------------------------------------------------------------------------
; DATE$: today's date as a 10-character string (dd.mm.yyyy, or mm/dd/yyyy in US mode).
; Entry: none
; Exit: a0 = temporary descriptor
;------------------------------------------------------------------------------
