	move.w	#$2a,-(sp)                      ; Tgetdate
	trap	#1                              ; Tgetdate
	addq.l	#2,sp                           ; drop the parameter
	move.l	d0,d7                           ; date
	moveq	#10,d0                          ; ten characters

