	dc.w	$6100,$0000                     ; bsr.w date_call_stcreat+2 -> STcreat (filled in by the linker), new
                                                ;   temporary string
	move.l	d7,d0                           ; the date
	exg	a1,a0                           ; write into its data
	bsr.s	format_date                     ; format the date
	movea.l	a1,a0                           ; descriptor
	rts

;------------------------------------------------------------------------------
; Formats a GEMDOS date as dd.mm.yyyy, or mm/dd/yyyy when the US date flag is set.
; Entry: d0.w = date, a0 = buffer
; Exit: a0 = after the text
;------------------------------------------------------------------------------
format_date:
	move.b	$61c(a6),d1                     ; US order?
	bmi.s	.us_order                       ; yes
	move.w	d0,d1                           ; date
	andi.w	#$1f,d0                         ; day
	bsr.w	put_two_digits                  ; day
	move.b	#$2e,(a0)+                      ; .
	move.w	d1,d0                           ; date
	lsr.w	#5,d0                           ; month
	andi.w	#$f,d0                          ; month
	bsr.s	put_two_digits                  ; two digits
	move.b	#$2e,(a0)+                      ; .
	bra.s	.year                           ; the year
.us_order:
	move.w	d0,d1                           ; date
	lsr.w	#5,d0                           ; month
	andi.w	#$f,d0                          ; month
	bsr.s	put_two_digits                  ; two digits
	move.b	#$2f,(a0)+                      ; /
	move.w	d1,d0                           ; date
	andi.w	#$1f,d0                         ; day
	bsr.s	put_two_digits                  ; day
	move.b	#$2f,(a0)+                      ; /
.year:
	rol.w	#7,d1                           ; year bits
	andi.l	#$7f,d1                         ; 0-127
	addi.l	#$7bc,d1                        ; from 1980
	divu.w	#$64,d1                         ; century and year
	bsr.s	put_value_digits                ; century
	swap	d1                              ; year in the century
	bra.s	put_value_digits                ; two digits and return

