format_time:
	pea	(a1)                            ; buffer
	move.w	#$2c,-(sp)                      ; Tgettime
	trap	#1                              ; Tgettime
	addq.l	#2,sp                           ; drop the parameter
	movea.l	(sp)+,a0                        ; buffer

;------------------------------------------------------------------------------
; Formats a GEMDOS time as hh:mm:ss.
; Entry: d0.w = time, a0 = buffer.
; Exit: a0 = after the text; d0-d1 changed.
;------------------------------------------------------------------------------
SubTimeS:
	move.w	d0,d1                           ; time
	rol.w	#5,d0                           ; hours
	andi.w	#$1f,d0                         ; 0-23
	bsr.s	put_two_digits                  ; two digits
	move.b	#$3a,(a0)+                      ; :
	move.w	d1,d0                           ; time
	lsr.w	#5,d0                           ; minutes
	andi.w	#$3f,d0                         ; 0-59
	bsr.s	put_two_digits                  ; two digits
	move.b	#$3a,(a0)+                      ; :
	andi.w	#$1f,d1                         ; seconds / 2
	add.w	d1,d1                           ; seconds

;------------------------------------------------------------------------------
