;------------------------------------------------------------------------------
; Writes d0 (0-99) as two decimal digits.
; Entry: d0.w = value, a0 = buffer
; Exit: a0 advanced
;------------------------------------------------------------------------------
put_two_digits:
	ext.l	d0                              ; tens and units
	divu.w	#$a,d0                          ; tens, units in the high word
	ori.l	#$20302030,d0                   ; both to digits
	move.b	d0,(a0)+                        ; tens
	swap	d0                              ; units
	move.b	d0,(a0)+                        ; units
	rts

