parse_field_fail:
	moveq	#-1,d1                          ; invalid
	rts

;------------------------------------------------------------------------------
; Reads a decimal number from a date or time field, stopping at "." or ":"; with a limit below 100 only two digits are
; read.
; Entry: a1 = text, d0.w = characters left, d2.w = highest value
; Exit: d1.w = value (Z if 0), N set and d1 = -1 if invalid; a1/d0 advanced
;------------------------------------------------------------------------------
parse_decimal_field:
	moveq	#0,d1                           ; value
	moveq	#0,d4
	subq.w	#1,d0                           ; characters left?
	bmi.s	parse_field_fail
	move.b	(a1)+,d1                        ; first character
	subi.b	#$30,d1
	cmpi.b	#$9,d1                          ; a digit?
	bhi.s	parse_field_fail
	subq.w	#1,d0                           ; more characters?
	bmi.s	parse_field_fail
.next_digit:
	move.b	(a1)+,d4                        ; next character
	cmpi.b	#$2e,d4                         ; dot ends the field
	beq.s	.separator
	cmpi.b	#$3a,d4                         ; colon ends the field
	beq.s	.separator
	subi.b	#$30,d4                         ; a digit?
	cmpi.b	#$9,d4
	bhi.s	parse_field_fail
	mulu.w	#$a,d1                          ; add the digit
	add.w	d4,d1
	cmp.w	d2,d1                           ; over the limit?
	bhi.s	parse_field_fail
	cmpi.w	#$64,d2                         ; two digits only?
	bcs.s	.done
	subq.w	#1,d0                           ; more characters?
	bpl.s	.next_digit
.done:
	tst.w	d1                              ; Z if the value is 0
	rts
.separator:
	subq.l	#1,a1                           ; leave the separator
	addq.w	#1,d0
	tst.w	d1                              ; Z if the value is 0
	rts

