; Length of a SPRITE string while the sprite is shown: the 74-byte Line-A sprite
; definition followed by its save area (planes * 64 + 10 bytes). Set by SPRITE a$,x,y.
sprite_full_length:
	dc.w	$e6fb

;------------------------------------------------------------------------------
; SPRITE a$: removes a sprite from the screen. A shown sprite's string holds the
; definition and the save area; the background is restored with the Line-A Undraw sprite
; and the string is cut back to the 74-byte definition.
; Entry: a0 = string variable.
; Exit: error 60 for a string of another length; d0-d2/a0-a2 changed.
;------------------------------------------------------------------------------
SPRITE:
	dc.w	$6100,$0000                     ; bsr.w	SPRITE+2 -> Hidem (filled in by the linker), hide the mouse
	movea.l	(a0)+,a1                        ; a1 = string data
	move.w	(a0),d0                         ; d0 = length
	cmpi.w	#$4a,d0                         ; only the definition: not shown
	beq.s	.done                           ; nothing to remove
	cmp.w	sprite_full_length(pc),d0       ; definition and save area?
	bne.s	sprite_error_length             ; no: error 60
	pea	(a0)                            ; keep the length field address
	lea	$4a(a1),a2                      ; a2 = save area
	movem.l	a4-a6,-(sp)                     ; Line-A changes a4-a6
	dc.w	$a00c                           ; Line-A Undraw sprite, restore the background
	movem.l	(sp)+,a4-a6                     ; restore a4-a6
	moveq	#74,d0                          ; 74: the definition alone
	movea.l	(sp)+,a2                        ; length field
	move.w	(a2),d2                         ; d2 = old length
	move.w	d0,(a2)                         ; new length
	movea.l	-(a2),a1                        ; a1 = data, a2 = descriptor
	move.l	a2,$4a(a1)                      ; back pointer after the 74 bytes
	subi.w	#$4e,d2                         ; rest of the old block (less the new back pointer)
	adda.w	d2,a1                           ; to the old back pointer
	ext.l	d2                              ; size of the rest
	neg.l	d2                              ; negative
	move.l	d2,$4e(a1)                      ; marks the rest of the block free
.done:
	rts

sprite_error_length:
	moveq	#60,d0                          ; error 60

sprite_call_error:
	dc.w	$6000,$0000                     ; bra.w sprite_call_error+2 -> ERROR (filled in by the linker), stop
                                                ;   with the error

;------------------------------------------------------------------------------
; SPRITE a$,x,y: draws a sprite at x,y with the Line-A Draw sprite, first removing it from
; its old place when it is shown. A definition-only string is extended by the save area.
; Entry: a0 = string variable, d1.w = x, d0.w = y.
; Exit: error 60 for a string of another length; d0-d3/a0-a2 changed.
;------------------------------------------------------------------------------
SPRITEXY:
