	move.w	d2,(a1)                         ; keep it

sprite_call_hidem:
	dc.w	$6100,$0000                     ; bsr.w sprite_call_hidem+2 -> Hidem (filled in by the linker), hide the
                                                ;   mouse
	movea.l	(a0)+,a1                        ; a1 = string data
