	cmpi.w	#$4a,d2                         ; only the definition: not shown yet
	beq.s	.extend                         ; first time: extend the string
	cmp.w	sprite_full_length(pc),d2       ; definition and save area?
	bne.s	sprite_error_length             ; no: error 60
	lea	$4a(a1),a2                      ; a2 = save area
	movem.l	d0-d1/a1/a6,-(sp)               ; keep x, y, data and a6
	dc.w	$a00c                           ; Line-A Undraw sprite, restore the old background
	movem.l	(sp)+,d0-d1/a0                  ; x, y and a0 = the definition
	lea	$4a(a0),a2                      ; a2 = save area
	exg	d1,d0                           ; d0 = x, d1 = y
	dc.w	$a00d                           ; Line-A Draw sprite, draw it
	movea.l	(sp)+,a6                        ; restore a6
