; FILES p$: long listing on the screen.
; Entry: a0 = path string.
;------------------------------------------------------------------------------
FILES1:
	moveq	#23,d0                          ; FILES attribute
	bra.s	dir_with_path                   ; list

;------------------------------------------------------------------------------
; DIR p$: short listing on the screen.
; Entry: a0 = path string.
;------------------------------------------------------------------------------
DIR1:
	moveq	#0,d0                           ; DIR attribute

dir_with_path:
	move.w	d0,dir_search_attribute-m_dir   ; keep the attribute

dir_call_xstr0kil:
	dc.w	$6100,$0000                     ; bsr.w dir_call_xstr0kil+2 -> XStr0Kil (filled in by the linker), a1 =
                                                ;   path text, d1 = length
	bra.s	dir_to_screen                   ; list on the screen

;------------------------------------------------------------------------------
; FILES: long listing of the current folder on the screen.
;------------------------------------------------------------------------------
FILES0:
	moveq	#23,d0                          ; FILES attribute
	bra.s	dir_no_path                     ; list

;------------------------------------------------------------------------------
; DIR: short listing of the current folder on the screen.
;------------------------------------------------------------------------------
DIR0:
	moveq	#0,d0                           ; DIR attribute

dir_no_path:
	moveq	#0,d1                           ; no path
	move.w	d0,dir_search_attribute-m_dir   ; keep the attribute

dir_to_screen:
	move.w	#$fffc,$48(a6)                  ; output to the screen (channel -4)

;------------------------------------------------------------------------------
; Lists the files matching the path: one name per line for DIR; for FILES a space or '*'
; for folders, the name, the size in 7 columns, the time and the date. Stops on Break.
; Entry: a1 = path text, d1.w = its length, dir_search_attribute set.
; Exit: error from Fsfirst / Fsnext other than no more files (output channel 87 closed).
;------------------------------------------------------------------------------
dir_list:
	lea	$4a(a6),a0                      ; build the search path in the text buffer
	tst.w	d1                              ; no path?
	beq.s	.wildcard                       ; yes: "*.*"
	move.w	#$fa,d0                         ; at most 250 characters
	cmp.w	d0,d1                           ; longer?
	bcs.s	.count_path                     ; no
	move.w	d0,d1                           ; cut it
	bra.s	.count_path                     ; into the loop
.copy_path:
	move.b	(a1)+,(a0)+                     ; copy the path
.count_path:
	dbra	d1,.copy_path                   ; all of it
	clr.b	(a0)                            ; zero terminate
	cmpi.b	#$3a,-(a0)                      ; ends with a drive colon?
	beq.s	.append_wildcard                ; yes: add "*.*"
	cmpi.b	#$5c,(a0)                       ; ends with a backslash?
	bne.s	.search                         ; no: use it as it is
.append_wildcard:
	addq.l	#1,a0                           ; after the last character
.wildcard:
	lea	dir_wildcard(pc),a1             ; "*.*"
.copy_wildcard:
	move.b	(a1)+,(a0)+                     ; copy it with its zero
	bne.s	.copy_wildcard                  ; up to the zero
.search:
	moveq	#-128,d0                        ; the DTA is the 128 bytes
	dc.w	$0680,$0000,$0000               ; addi.l #$0,d0 -> STARTADR (filled in by the linker), before the
                                                ;   program start (command line area)

dir_call_fsetdta:
	dc.w	$6100,$0000                     ; bsr.w	dir_call_fsetdta+2 -> FSETDTA (filled in by the linker), Fsetdta
	move.w	dir_search_attribute-m_dir,-(sp) ; attribute
	pea	$4a(a6)                         ; search path
	move.w	#$4e,-(sp)                      ; Fsfirst
	trap	#1                              ; Fsfirst
	addq.l	#8,sp                           ; drop the parameters

dir_next_entry:
	btst	#$1,$136e(a6)                   ; Break pressed?
	bne.s	dir_return                      ; yes: stop
	tst.l	d0                              ; found a file?
	bpl.s	dir_show_entry                  ; yes: show it
	cmpi.w	#$ffdf,d0                       ; -33: file not found
	beq.s	dir_return                      ; done
	cmpi.w	#$ffcf,d0                       ; -49: no more files
	beq.s	dir_return                      ; done
	move.w	d0,-(sp)                        ; keep the error
	moveq	#87,d0                          ; channel 87

dir_call_close_error:
	dc.w	$6100,$0000                     ; bsr.w dir_call_close_error+2 -> CLOSE (filled in by the linker), close
                                                ;   the output file
	move.w	(sp)+,d0                        ; the error

dir_call_error:
	dc.w	$6000,$0000                     ; bra.w dir_call_error+2 -> ERROR (filled in by the linker), stop with
                                                ;   it

dir_return:
	rts

dir_show_entry:
	lea	$4a(a6),a1                      ; build the line in the text buffer
	dc.w	$45f9,$0000,$0000               ; lea	$0,a2 -> STARTADR (filled in by the linker), program start
	lea	-$80(a2),a2                     ; a2 = DTA
	lea	$1e(a2),a0                      ; a0 = file name
	tst.w	dir_search_attribute-m_dir      ; DIR?
	beq.s	.copy_name                      ; yes: name only
	move.b	#$20,(a1)+                      ; FILES: leading space
	btst	#$4,$15(a2)                     ; folder?
	beq.s	.copy_name                      ; no
	move.b	#$2a,-$1(a1)                    ; mark folders with '*'
.copy_name:
	move.b	(a0)+,(a1)+                     ; copy the name
	bne.s	.copy_name                      ; up to the zero
	subq.l	#1,a1                           ; back on the zero
	tst.w	dir_search_attribute-m_dir      ; DIR?
	beq.s	dir_end_line                    ; yes: end the line
	lea	$59(a6),a0                      ; column 15
.pad_name:
	move.b	#$20,(a1)+                      ; pad with spaces
	cmpa.l	a0,a1                           ; up to column 15
	bne.s	.pad_name
	move.l	$1a(a2),d0                      ; file size
	bsr.s	dir_put_size                    ; as 7 digits with leading spaces
	tst.b	d1                              ; any digit written?
	bne.s	.time                           ; yes
	st	d1                              ; size 0
	move.b	#$30,-$1(a1)                    ; last digit '0'
.time:
	move.w	$16(a2),d0                      ; file time
	move.b	#$20,(a1)+                      ; space
	movea.l	a1,a0                           ; at a0

dir_call_subtimes:
	dc.w	$6100,$0000                     ; bsr.w dir_call_subtimes+2 -> SubTimeS (filled in by the linker),
                                                ;   hh:mm:ss
	move.b	#$20,(a0)+                      ; space
	move.w	$18(a2),d0                      ; file date

dir_call_subdates:
	dc.w	$6100,$0000                     ; bsr.w dir_call_subdates+2 -> SubDateS (filled in by the linker), the
                                                ;   date
	movea.l	a0,a1                           ; end of the text

dir_end_line:
	move.b	#$d,(a1)+                       ; CR
	move.b	#$a,(a1)+                       ; LF
	suba.w	#$4a,a1                         ; line length:
	suba.l	a6,a1                           ; from the text buffer
	move.l	a1,d0                           ; d0 = length
	lea	$4a(a6),a1                      ; text buffer

dir_call_xprsub:
	dc.w	$6100,$0000                     ; bsr.w dir_call_xprsub+2 -> Xprsub (filled in by the linker), print the
                                                ;   line

dir_call_fsnext:
	dc.w	$6100,$0000                     ; bsr.w	dir_call_fsnext+2 -> FSNEXT (filled in by the linker), Fsnext
	bra.w	dir_next_entry                  ; next entry

;------------------------------------------------------------------------------
; Writes a file size (below 10,000,000) as 7 decimal digits, leading zeros as spaces.
; Entry: d0.l = size, a1 = buffer.
; Exit: a1 advanced; d1.b non-zero once a digit was written; d0 changed.
;------------------------------------------------------------------------------
dir_put_size:
	divu.w	#$2710,d0                       ; millions and below / 10000
	move.l	d0,-(sp)                        ; keep the remainder
	sf	d1                              ; no digit yet
	bsr.s	dir_put_three_digits            ; the top 3 digits
	move.l	(sp)+,d0                        ; remainder
	swap	d0                              ; in the low word
	ext.l	d0                              ; as a long
	divu.w	#$3e8,d0                        ; thousands digit
	bsr.s	dir_put_digit                   ; write it, then the last 3 digits

;------------------------------------------------------------------------------
; Writes a value below 1000 as 3 digits (hundreds, tens, units).
; Entry: d0.w = value, a1 = buffer, d1.b = digit seen flag.
;------------------------------------------------------------------------------
dir_put_three_digits:
	ext.l	d0                              ; as a long
	divu.w	#$64,d0                         ; hundreds
	bsr.s	dir_put_digit                   ; write it
	ext.l	d0                              ; as a long
	divu.w	#$a,d0                          ; tens
	bsr.s	dir_put_digit                   ; write it
	nop                                     ; then the units

;------------------------------------------------------------------------------
; Writes the digit in d0.b, a space while only zeros have come, and takes the remainder
; from the high word.
; Entry: d0 = remainder:digit, d1.b = digit seen flag, a1 = buffer.
; Exit: d0.l = remainder; a1 advanced.
;------------------------------------------------------------------------------
dir_put_digit:
	tst.b	d1                              ; a digit already written?
	bne.s	.digit                          ; yes: write a digit
	tst.b	d0                              ; leading zero?
	beq.s	.store                          ; yes: a space
.digit:
	ori.b	#$30,d0                         ; to '0'-'9'
	st	d1                              ; digits from now on
.store:
	ori.b	#$20,d0                         ; 0 becomes a space
	move.b	d0,(a1)+                        ; write it
	swap	d0                              ; remainder
	ext.l	d0                              ; as a long
	rts

