;==============================================================================
; Module QUSORT.O: 344 bytes of code, 0 of data, 0 of bss; exports UPDWUX, UPDWSX, UPDWS, UPDWU, ShellIt, QuickIt
;==============================================================================
	dc.b	$51,$55,$53,$4f,$52,$54,$2e,$4f,$00,$00,$00,$00,$00,$00	; library entry: the name QUSORT.O
	dc.w	$74f8,$1675,$0000,$01b6,$0000,$032e,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$158,$0,$0,$62		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_qusort:
;------------------------------------------------------------------------------
; Sort set-up for unsigned keys with a companion array (QSORT/SSORT a(),n,b%()).
; As UPDWU, then a2 = the companion array's elements.
;------------------------------------------------------------------------------
UPDWUX:
	bsr.s	UPDWU                           ; set up the compares

qusort_companion:
	movea.l	(a2)+,a2                        ; companion array data
	addq.l	#4,a2                           ; skip its element count
	rts

;------------------------------------------------------------------------------
; Sort set-up for a signed key array with a companion array.
; As UPDWS, then a2 = the companion array's elements.
;------------------------------------------------------------------------------
UPDWSX:
	pea	qusort_companion(pc)            ; a2 from the companion array afterwards

;------------------------------------------------------------------------------
; Sort set-up for signed keys: patches the conditional branches after the compares in
; ShellIt and QuickIt to bge (ascending) or ble (descending, d7 negative), checks the array
; and works out the range.
; Entry: a0 = array variable, a1 = companion array variable, a2 = sort routine, d0.l =
; elements to sort, d7.b sign = order.
; Exit: d6 = sort routine, a2 = companion array variable, a3 = elements (old a3 in
; $20(a6)), d0 = 0, d1 = last index.
;------------------------------------------------------------------------------
UPDWS:
	moveq	#108,d4                         ; bge
	tst.b	d7                              ; descending?
	bpl.s	qusort_patch_branches           ; no
	moveq	#111,d4                         ; ble
	bra.s	qusort_patch_branches           ; patch them

;------------------------------------------------------------------------------
; Sort set-up for unsigned keys: as UPDWS with bcc (ascending) or bls (descending).
;------------------------------------------------------------------------------
UPDWU:
	moveq	#100,d4                         ; bcc
	tst.b	d7                              ; descending?
	bpl.s	qusort_patch_branches           ; no
	moveq	#99,d4                          ; bls

qusort_patch_branches:
	move.l	a2,d6                           ; keep the sort routine
	lea	ShellIt(pc),a2                  ; code to patch
	move.b	d4,$1a(a2)                      ; ShellIt: after the compare
	move.b	d4,$60(a2)                      ; QuickIt: first compare
	move.b	d4,$82(a2)                      ; QuickIt: first against the middle
	move.b	d4,$94(a2)                      ; QuickIt: scan up
	move.b	d4,$a4(a2)                      ; QuickIt: scan down
	eori.b	#$1,d4                          ; the opposite condition
	move.b	d4,$7a(a2)                      ; QuickIt: median compare
	movea.l	(a0)+,a2                        ; array data
	cmpi.w	#$1,(a0)                        ; one dimension?
	bne.s	.error_dimensions               ; no: error 28
	move.l	a3,$20(a6)                      ; keep the local stack top
	move.l	(a2)+,d3                        ; element count
	cmp.l	d3,d0                           ; fewer to sort than there are?
	bcs.s	.range                          ; yes: keep it
	move.l	d3,d0                           ; at most all of them
.range:
	move.l	d0,d1                           ; elements to sort
	movea.l	a2,a3                           ; a3 = the elements
	movea.l	a1,a2                           ; a2 = companion array variable
	moveq	#0,d0                           ; first index 0
	subq.l	#1,d1                           ; last index
	rts
.error_dimensions:
	moveq	#28,d0                          ; error 28: not one-dimensional

qusort_call_error:
	dc.w	$6000,$0000                     ; bra.w qusort_call_error+2 -> ERROR (filled in by the linker), stop
                                                ;   with the error

qusort_shell_fallback:
	movem.l	qusort_saved_range(pc),d0-d1/sp ; stack too deep: whole range and stack back, Shell sort instead

;------------------------------------------------------------------------------
; Shell sort of elements d0..d1 with the compare routine at a1 (flags for elements d4,d5)
; and the swap routine at a0 (swaps elements d4,d5). The branch after the compare is
; patched by the sort set-up.
; Entry: d0 = first index (0), d1 = last index.
; Exit: d0-d5 changed.
;------------------------------------------------------------------------------
ShellIt:
	move.l	d1,d0                           ; gap = count / 2
	lsr.l	#1,d0
	bne.s	.next_gap                       ; not 0
	bcc.s	.done                           ; one element: done
	addq.l	#1,d0                           ; gap 1
.next_gap:
	move.l	d0,d2                           ; i = gap
.next_i:
	move.l	d2,d3                           ; j = i - gap
	sub.l	d0,d3                           ; below 0: next i
	bmi.s	.step_i
.compare:
	move.l	d3,d4                           ; element j
	move.l	d0,d5                           ; element j + gap
	add.l	d4,d5                           ; d5 = j + gap
	jsr	(a1)                            ; compare them
	bcc.s	.step_i                         ; in order (patched): next i
	jsr	(a0)                            ; swap them
	sub.l	d0,d3                           ; j = j - gap
	bpl.s	.compare                        ; again while j >= 0
.step_i:
	addq.l	#1,d2                           ; next i
	cmp.l	d1,d2                           ; up to the last index
	ble.s	.next_i                         ; more
	lsr.l	#1,d0                           ; halve the gap
	bne.s	.next_gap                       ; until it is 0
.done:
	rts

; Lowest stack address QuickIt may reach before it falls back to the Shell sort.
qusort_stack_limit:
	dc.w	$0000,$0000

; First and last index and stack pointer at the start of QuickIt.
qusort_saved_range:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000

;------------------------------------------------------------------------------
; Quick sort of elements d0..d1 with the compare routine at a1 and the swap routine at
; a0, median of three pivot, recursing on the left part and looping on the right part.
; right. Falls back to ShellIt when the stack would go 1000 bytes deeper.
; Entry: d0 = first index, d1 = last index.
; Exit: d0-d7 changed.
;------------------------------------------------------------------------------
QuickIt:
	move.l	sp,d7                           ; stack limit
	subi.l	#$3e8,d7                        ; 1000 bytes below the start
	move.l	d7,qusort_stack_limit-m_qusort  ; keep it
	movem.l	d0-d1/sp,qusort_saved_range-m_qusort ; keep the range and the stack for the fallback

qusort_quick_range:
	cmpa.l	qusort_stack_limit(pc),sp       ; stack too deep?
	bcs.s	qusort_shell_fallback           ; yes: Shell sort everything
	move.l	d0,d4                           ; first
	move.l	d1,d5                           ; last
	jsr	(a1)                            ; compare them
	bcc.s	.ordered                        ; in order (patched)
	jsr	(a0)                            ; swap first and last
.ordered:
	move.l	d0,d2                           ; i = first
	move.l	d1,d3                           ; j = last
	addq.l	#1,d2                           ; i + 1
	cmp.l	d2,d3                           ; two elements only?
	beq.s	.done                           ; yes: done
	move.l	d0,d2                           ; i = first
	move.l	d0,d4                           ; middle
	add.l	d1,d4                           ; = (first + last)
	lsr.l	#1,d4                           ; / 2
	move.l	d1,d5                           ; last
	jsr	(a1)                            ; compare middle and last
	bcs.s	.swap_pivot                     ; out of order (patched): swap them
	move.l	d4,d5                           ; compare first with the middle
	move.l	d0,d4                           ; first
	jsr	(a1)                            ; compare
	bcc.s	.pivot                          ; in order (patched)
.swap_pivot:
	jsr	(a0)                            ; swap
.pivot:
	move.l	d5,d4                           ; d4 = pivot index
.scan_from_pivot:
	move.l	d4,d5                           ; d5 = pivot
.scan_up:
	addq.l	#1,d2                           ; i + 1
	cmp.l	d2,d3                           ; met j?
	ble.s	.partition_end                  ; yes: partition done
	move.l	d2,d4                           ; element i
	jsr	(a1)                            ; compare with the pivot
	bcc.s	.scan_up                        ; smaller (patched): go on
	subq.l	#1,d2                           ; back one
	move.l	d5,d4                           ; pivot
.scan_down:
	subq.l	#1,d3                           ; j - 1
	cmp.l	d2,d3                           ; met i?
	ble.s	.recurse                        ; yes
	move.l	d3,d5                           ; element j
	jsr	(a1)                            ; compare with the pivot
	bcc.s	.scan_down                      ; larger (patched): go on
	exg	d4,d2                           ; d4 = i, d2 = pivot
	move.l	d3,d5                           ; d5 = j
	addq.l	#1,d3                           ; step past them
	addq.l	#1,d4                           ; i + 1
	jsr	(a0)                            ; swap elements i + 1 and j
	cmp.l	d2,d4                           ; pivot moved with i?
	bne.s	.check_pivot                    ; no
	move.l	d5,d2                           ; pivot now at j
.check_pivot:
	cmp.l	d2,d5                           ; pivot moved with j?
	bne.s	.next_pair                      ; no
	move.l	d4,d2                           ; pivot now at i
.next_pair:
	subq.l	#1,d4                           ; i back
	exg	d2,d4                           ; d2 = i, d4 = pivot
	bra.s	.scan_from_pivot                ; scan on
.partition_end:
	subq.l	#1,d2                           ; back one
	move.l	d5,d4                           ; pivot
.recurse:
	cmp.l	d2,d0                           ; left part longer than one?
	bge.s	.right_only                     ; no
