;------------------------------------------------------------------------------
; Divides a float in memory by 2^d3, kept as data words that load the float from (a0).
;------------------------------------------------------------------------------
float_div_pow2_stored:
	move.l	(a0)+,d0                        ; move.l (a0)+,d0 / move.w (a0)+,d1 / move.w (a0)+,d2
	move.w	(a0)+,d1
	move.w	(a0)+,d2

;------------------------------------------------------------------------------
; Divides a float by 2^d3 by moving its exponent word towards zero; a result too small gives 0. float_div_pow2_stored
; before it first loads the float from (a0).
; Entry: d0.l/d1.w = mantissa, d2.w = signed exponent, d3.w = power of two.
; Exit: d2 = new exponent (0 on underflow).
;------------------------------------------------------------------------------
float_div_pow2:
	tst.w	d2                              ; sign of the number is the sign of the exponent word
	bmi.s	.negative                       ; negative number
	sub.w	d3,d2                           ; positive: lower the exponent
	bmi.s	.underflow                      ; gone below zero: underflow
.done:
	rts
.negative:
	add.w	d3,d2                           ; negative: raise the exponent towards zero
	bmi.s	.done                           ; still negative: done
.underflow:
	moveq	#0,d2                           ; too small: the result is 0
	rts

;------------------------------------------------------------------------------
; Halves a float in memory.
; Entry: a0 -> float
; Exit: d0-d2
;------------------------------------------------------------------------------
float_halve_stored:
	move.l	(a0)+,d0                        ; entry with the float at (a0): load it into d0/d1/d2
	move.w	(a0)+,d1
	move.w	(a0)+,d2

;------------------------------------------------------------------------------
; Halves a float by moving its exponent word one step towards zero; zero stays zero. float_halve_stored before it first
; loads the float from (a0).
; Entry: d0.l/d1.w = mantissa, d2.w = signed exponent.
; Exit: d2 = new exponent.
;------------------------------------------------------------------------------
float_halve:
	tst.w	d2                              ; zero or negative?
	ble.s	.not_positive
	subq.w	#1,d2                           ; positive: one step down
.done:
	rts
.not_positive:
	beq.s	.done                           ; zero stays zero
	addq.w	#1,d2                           ; negative: one step up
	rts

