	movea.l	(a0)+,a1                        ; buffer
	movem.w	(a0),d0-d2                      ; size, head, tail
	moveq	#0,d0                           ; nothing
	cmp.w	d1,d2                           ; empty?
	beq.s	.done                           ; yes
	cmp.w	(a0),d1                         ; head at the end?
	bcs.s	.read_entry                     ; no
	moveq	#-4,d1                          ; wrap to the start
.read_entry:
	move.l	4(a1,d1.w),d0                   ; entry after the head
.done:
	move.l	d0,d1
	rts

