;------------------------------------------------------------------------------
; Line editor for INPUT, starting with text already in the line buffer. Control characters are accepted.
; Entry: d0 = maximum length, d6 = length of the text already in the line buffer.
; Exit: as edit_line.
;------------------------------------------------------------------------------
edit_line_preset:
	clr.w	$137a(a6)                       ; control characters are accepted
	bra.s	edit_line

;------------------------------------------------------------------------------
; Line editor with an empty line, 255 characters at most, control characters accepted (input from the keyboard channel).
; Exit: as edit_line.
;------------------------------------------------------------------------------
edit_line_any_char:
	moveq	#-1,d0                          ; 255 characters at most
	clr.w	$137a(a6)                       ; control characters are accepted
	bra.s	edit_line_empty

