	move.w	(a1)+,d1
	move.w	(a1)+,d2

;------------------------------------------------------------------------------
; MIN of a float and a float in memory.
; Entry: d0-d2 = float, a0 -> float
; Exit: d0-d2 = the smaller
;------------------------------------------------------------------------------
