	move.w	(a0)+,d4
	move.w	(a0)+,d5

;------------------------------------------------------------------------------
; MIN of two floats: keeps the smaller.
; Entry: d0-d2, d3-d5 = floats
; Exit: d0-d2 = the smaller
;------------------------------------------------------------------------------
float_min:
