	tst.w	d2                              ; same exponent: compare the mantissas
	bpl.s	.positive
	cmp.l	d0,d3                           ; negative: the smaller mantissa is larger
	bhi.s	.done
	bne.s	.take_second
	cmp.w	d1,d4                           ; same high long: low words
	bcc.s	.done
	bra.s	.take_second
.positive:
	cmp.l	d0,d3                           ; positive: the larger mantissa is larger
	bcs.s	.done
	bne.s	.take_second
	cmp.w	d1,d4                           ; same high long: low words
	bls.s	.done
.take_second:
