	cmpi.w	#$13,d0                         ; beyond 20?
	bhi.s	.done                           ; yes: ignore
	asl.w	#5,d0                           ; * 32
	dc.w	$41f9,$0000,$0000               ; lea $0,a0 -> KEYBUF (filled in by the linker), lea $0,a0 -> KEYBUF
                                                ;   (filled in by the linker), function key texts
	adda.w	d0,a0                           ; this key's entry
	cmpi.w	#$1f,d1                         ; 31 or more?
	bcs.s	.copy_next                      ; no
	moveq	#30,d1                          ; cut to 30
.copy_char:
	move.b	(a1)+,(a0)+                     ; copy a character
.copy_next:
	dbra	d1,.copy_char
	clr.b	(a0)+                           ; terminate it
.done:
	rts

