m_keyirq:
EtVAL:
	dc.w	$0000,$0000

; EVERY timer: the time (_hz_200) of the next event and a copy of it; the long before it is the interval. Nothing in the
; program sets them.
every_due:
	dc.w	$0000,$0000,$0000,$0000

; AFTER timer: the time (_hz_200) of the one event, and a spare long. Nothing in the program sets them.
after_due:
	dc.w	$0000,$0000,$0000,$0000

;------------------------------------------------------------------------------
; etv_timer handler: calls the previous handler (its address is patched into the jsr) and then checks the keys and
; timers in event_poll.
; Entry: 4(sp) = timer period word.
;------------------------------------------------------------------------------
timer_hook:
	move.w	4(sp),-(sp)                     ; pass the timer period on
	jsr	$0                              ; previous etv_timer handler, patched in
	addq.l	#2,sp                           ; drop the period word
	bra.s	event_poll                      ; then the checks

;------------------------------------------------------------------------------
; Seed-fill abort routine set into Line-A when a break is pending: returns -1 to stop the fill.
;------------------------------------------------------------------------------
fill_abort:
	moveq	#-1,d0                          ; -1: abort the fill
	rts

;------------------------------------------------------------------------------
; Keyboard interrupt hook (Kbdvbase ikbdsys): calls the previous handler (patched into the jsr), then checks the new key
; in event_poll.
;------------------------------------------------------------------------------
ikbd_hook:
	jsr	$0                              ; previous ikbdsys handler, patched in

;------------------------------------------------------------------------------
; Common part of the timer and keyboard hooks: points a6 at the runtime block and checks for a break, the new key and
; the timers.
; Exit: d3-d4/a6 restored.
;------------------------------------------------------------------------------
event_poll:
	movem.l	d3-d4/a6,-(sp)                  ; keep the registers the hooks use
	dc.w	$4df9,$0000,$0000               ; lea	$0,a6 -> BssA6 (filled in by the linker), the runtime block

;------------------------------------------------------------------------------
; Break check: Left Shift+Control+Alternate held sets the break event (bit 1 of the event flags) unless ON BREAK CONT is
; set, and makes Line-A seed fills stop. The kbshift address in the lea is patched for TOS versions after 1.00.
;------------------------------------------------------------------------------
check_break_keys:
	lea	$e1b.w,a0                       ; kbshift (patched for the TOS version)
	moveq	#14,d0                          ; Left Shift, Control, Alternate
	and.b	(a0),d0                         ; held shift keys
	cmpi.b	#$e,d0                          ; all three held?
	bne.s	check_new_key                   ; no break
	dc.w	$1239,$0000,$0000               ; move.b	$0,d1 -> NoBREAK (filled in by the linker), break mode
	bmi.s	check_new_key                   ; ON BREAK CONT
	bset	#$1,$136e(a6)                   ; break event
	movea.l	$34(a6),a0                      ; Line-A base
	move.l	#fill_abort-m_keyirq,$76(a0)    ; SEEDABORT: stop a fill in progress

;------------------------------------------------------------------------------
; Looks at the newest key in the keyboard buffer (Iorec address patched into the movea) and applies the keyboard options
; in the keyboard flags: function key texts (bit 4 plain, bit 5 with Alternate), Alternate+keypad digits for a character
; code (bit 3), Control+keypad (bit 2) or keypad mode (bit 0) for cursor keys, and Control+keypad ( or - to toggle
; keypad mode (bit 1). Runs with interrupts off.
;------------------------------------------------------------------------------
check_new_key:
	movea.l	#$0,a0                          ; keyboard Iorec (patched in)
	ori.w	#$700,sr                        ; interrupts off
	dc.w	$1839,$0000,$0000               ; move.b $0,d4 -> NumLOCK (filled in by the linker), keyboard flags
	movea.l	(a0)+,a1                        ; buffer address
	movem.w	(a0),d0-d2                      ; d0 = size, d1 = head, d2 = tail
	moveq	#0,d3                           ; code being typed, zero-extended
	move.b	alt_code(pc),d3                 ; Alternate+keypad code being typed?
	beq.s	.check_key                      ; none
	movea.w	check_break_keys+2(pc),a2       ; kbshift address
	btst	#$3,(a2)                        ; Alternate still held?
	beq.w	insert_alt_code                 ; released: insert the typed code
.check_key:
	cmp.w	d1,d2                           ; no new key
	beq.w	check_timers
	move.w	0(a1,d2.w),d3                   ; newest key: shift state and scan code
	cmpi.b	#$63,d3                         ; Control+keypad (
	beq.w	toggle_keypad_mode              ; toggle keypad mode
	cmpi.b	#$4a,d3                         ; Control+keypad -
	beq.w	toggle_keypad_mode              ; toggle keypad mode
	cmpi.b	#$3b,d3                         ; below F1
	bcs.s	.check_keypad                   ; not a function key
	cmpi.b	#$5d,d3                         ; above Shift+F10
	bhi.s	.check_keypad                   ; not a function key
	cmpi.b	#$54,d3                         ; Shift+F1 to F10 become 10 to 19
	bcs.s	.check_unshifted                ; F1 to F10?
	subi.b	#$f,d3                          ; Shift+F1 to F10: scan code - 15
	bra.s	.function_key                   ; number it
.check_unshifted:
	cmpi.b	#$44,d3                         ; not F1 to F10
	bhi.s	.check_keypad                   ; beyond F10
.function_key:
	subi.b	#$3b,d3                         ; function key number 0-19
	btst	#$b,d3                          ; Alternate held?
	beq.s	.check_text                     ; no Alternate: bit 4 enables them
	lsr.b	#1,d4                           ; then bit 5 enables the texts
.check_text:
	btst	#$4,d4                          ; function key texts enabled?
	bne.w	insert_function_key             ; yes: replace the key with its text
.check_keypad:
	subi.b	#$67,d3                         ; keypad 7 8 9 4 5 6 1 2 3 0 . become 0-10
	cmpi.b	#$a,d3                          ; a keypad digit or '.'?
	bhi.s	check_timers                    ; no: leave the key
	btst	#$3,d4                          ; Alternate+keypad codes enabled?
	beq.s	.check_control                  ; no
	btst	#$b,d3                          ; Alternate held?
	bne.s	.alt_digit                      ; yes: add a digit to the code
.check_control:
	btst	#$2,d4                          ; Control+keypad cursor keys enabled?
	beq.s	.check_mode                     ; no
	btst	#$a,d3                          ; Control held?
	bne.s	.cursor_key                     ; yes: make it a cursor key
.check_mode:
	btst	#$0,d4                          ; keypad mode on?
	beq.s	check_timers                    ; no: leave the key
.cursor_key:
	ext.w	d3                              ; replace the key with the cursor key from the table
	asl.w	#2,d3                           ; 4 bytes per table entry
	move.l	keypad_cursor_table(pc,d3.w),0(a1,d2.w) ; replace the key in the buffer
	bra.s	check_timers                    ; done with the key
.alt_digit:
	ext.w	d3                              ; keypad '.' does nothing
	moveq	#10,d4                          ; index of keypad '.'
	cmp.w	d4,d3                           ; is it '.'?
	beq.s	check_timers                    ; yes: ignore it
	mulu.w	alt_code_word(pc),d4            ; code so far * 10 ...
	add.b	keypad_digit_table(pc,d3.w),d4  ; ... plus the digit
	move.b	d4,alt_code-m_keyirq            ; code being typed

;------------------------------------------------------------------------------
; Removes the newest key from the keyboard buffer.
; Entry: a0 = Iorec, d0 = size, d2 = tail.
;------------------------------------------------------------------------------
drop_new_key:
	subq.w	#4,d2                           ; one key back
	bpl.s	.store_tail                     ; no wrap
	add.w	d0,d2                           ; wrap round
.store_tail:
	move.w	d2,4(a0)                        ; new tail: key removed

;------------------------------------------------------------------------------
; Checks the EVERY and AFTER timers against _hz_200: a due EVERY sets event bit 2 and is rescheduled, a due AFTER sets
; event bit 3 and is cleared. Then returns from the hook.
;------------------------------------------------------------------------------
check_timers:
	lea	every_due(pc),a0                ; EVERY timer
	move.l	(a0),d0                         ; EVERY due time
	beq.s	.check_after                    ; not running
	cmp.l	$4ba.w,d0                       ; _hz_200
	bhi.s	.check_after                    ; not due yet
	add.l	-$4(a0),d0                      ; add the interval
	move.l	d0,(a0)+                        ; next due time
	move.l	d0,(a0)+                        ; and its copy
	bset	#$2,$136e(a6)                   ; EVERY event
.check_after:
	lea	after_due(pc),a0                ; AFTER timer
	move.l	(a0),d0                         ; AFTER due time
	beq.s	.done                           ; not running
	cmp.l	$4ba.w,d0                       ; _hz_200
	bcc.s	.done                           ; not due yet
	clr.l	(a0)+                           ; one event only
	clr.l	(a0)                            ; and its spare long
	bset	#$3,$136e(a6)                   ; AFTER event
.done:
	movem.l	(sp)+,d3-d4/a6                  ; restore the registers of the hooks
	rts                                     ; back to the interrupted code

;------------------------------------------------------------------------------
; Digit for each keypad key in scan code order 7 8 9 4 5 6 1 2 3 0.
;------------------------------------------------------------------------------
keypad_digit_table:
	movep.w	$904(a0),d3                     ; data: digits 7 8 9 4 5 6 1 2 3 0, not code
	btst	d2,d6                           ; data
	btst	d0,d2                           ; data
	btst	d1,d0                           ; data

;------------------------------------------------------------------------------
; Key code (shift state, scan code, character) that replaces each keypad key in keypad mode: Clr/Home, up, Shift+up,
; left, nothing, right, Control+Z, down, Shift+down, Insert, Delete.
;------------------------------------------------------------------------------
keypad_cursor_table:
	subi.w	#$0,$48(sp,d0.w)                ; data: key codes, not code
	dc.w	$0000,$0448,$0000,$004b,$0000,$0000,$0000,$004d
	dc.w	$0000
	subi.b	#$1a,(a5)+                      ; data
	ori.w	#$0,(a0)                        ; data
	subi.w	#$0,(a0)                        ; data
	ori.w	#$0,(a2)                        ; data
	ori.b	#$7f,(a5)+                      ; data

;------------------------------------------------------------------------------
; Control with keypad ( or - toggles keypad mode (bit 0 of the keyboard flags) when bit 1 allows it, and the key is
; removed.
;------------------------------------------------------------------------------
toggle_keypad_mode:
	btst	#$a,d3                          ; Control held?
	beq.s	m_keyirq_key_done               ; no Control: ignore
	btst	#$1,d4                          ; toggling allowed?
	beq.s	m_keyirq_key_done               ; not allowed: ignore
	dc.w	$0879,$0000,$0000,$0000         ; bchg	#$0,$0 -> NumLOCK (filled in by the linker), keypad mode on/off
	bra.w	drop_new_key                    ; and remove the key

;------------------------------------------------------------------------------
; Alternate released after typing a code on the keypad: puts the character with that code in the keyboard buffer.
;------------------------------------------------------------------------------
insert_alt_code:
	clr.w	alt_code_word-m_keyirq          ; code done
	addq.w	#4,d2                           ; next buffer slot
	cmp.w	d0,d2                           ; past the end?
	bcs.s	.check_full                     ; wrap round
	moveq	#0,d2                           ; wrap round to slot 0
.check_full:
	cmp.w	d1,d2                           ; buffer full: lose it
	beq.s	m_keyirq_key_done               ; full
	move.w	d2,4(a0)                        ; new tail
	move.l	d3,0(a1,d2.w)                   ; the typed character

;------------------------------------------------------------------------------
; Goes on to the timer check.
;------------------------------------------------------------------------------
m_keyirq_key_done:
	bra.w	check_timers                    ; to the timers

;------------------------------------------------------------------------------
; Replaces a function key in the keyboard buffer with its text from the KEYDEF table (20 texts of 32 bytes). Esc gets
; its scan code, CR becomes Return.
; Entry: d3 = function key number 0-19, a0 = Iorec, a1 = buffer, d2 = tail.
;------------------------------------------------------------------------------
insert_function_key:
	ext.w	d3                              ; function key number as a word
	asl.w	#5,d3                           ; 32 bytes per text
	pea	(a3)                            ; keep a3
	lea	$0,a3                           ; function key texts
	adda.w	d3,a3                           ; this key's text
.next_char:
	moveq	#0,d3                           ; clear the scan code part
	move.b	(a3)+,d3                        ; next character
	beq.s	.done                           ; end of the text
	move.w	d2,4(a0)                        ; the new tail
	cmpi.b	#$1b,d3                         ; Esc
	bne.s	.check_cr                       ; not Esc
	bset	#$10,d3                         ; with scan code 1
.check_cr:
	cmpi.b	#$d,d3                          ; CR
	bne.s	.store_key                      ; not CR
	move.l	#$1c000d,d3                     ; as the Return key
.store_key:
	move.l	d3,0(a1,d2.w)                   ; into the buffer
	addq.w	#4,d2                           ; next slot
	cmp.w	d0,d2                           ; past the end?
	bcs.s	.check_full                     ; wrap round
	moveq	#0,d2                           ; wrap round to slot 0
.check_full:
	cmp.w	d1,d2                           ; stop when the buffer is full
	bne.s	.next_char                      ; more room: next character
.done:
	movea.l	(sp)+,a3                        ; restore a3
	bra.w	check_timers                    ; to the timers

; Alternate+keypad character code being typed, as a word (high byte always 0).
alt_code_word:
	dc.b	$00

; Low byte of the Alternate+keypad character code being typed.
alt_code:
	dc.b	$00

;------------------------------------------------------------------------------
; IRQON: hooks the keyboard and timer (break key, function key texts, keypad, EVERY/AFTER), once. Also makes
; the\nbetween-statement call (IRQPATCH) jump to IRQCHK and makes the exit code remove the hooks again.\nExit:
; d0-d1/a0-a2 changed
;------------------------------------------------------------------------------
IRQON:
	lea	remove_keyboard_hooks-m_keyirq,a0 ; install entry (no label): hooks the keyboard and timer once
	dc.w	$43f9,$0000,$0000               ; lea $0,a1 -> ExitAdr (filled in by the linker), jsr address in the
                                                ;   exit code
	cmpa.l	(a1),a0                         ; already installed?
	beq.s	.done                           ; yes: nothing to do
	move.l	a0,(a1)                         ; the exit code removes the hooks again
	pea	$e0001                          ; Iorec(1): keyboard
	trap	#14                             ; XBIOS
	move.l	d0,check_new_key+2-m_keyirq     ; patch the Iorec address
	dc.w	$13fc,$002e,$0000,$0000         ; move.b #$2e,$0 -> NumLOCK (filled in by the linker), default keyboard
                                                ;   flags
	move.w	#$22,(sp)                       ; Kbdvbase
	trap	#14                             ; XBIOS
	movea.l	d0,a0                           ; Kbdvbase table
	lea	$20(a0),a0                      ; ikbdsys vector
	lea	ikbd_hook(pc),a1                ; our hook keeps the old one in its jsr
	move.l	(a0),2(a1)                      ; old handler into the hook's jsr
	move.l	a1,(a0)                         ; install it
	clr.l	(sp)                            ; Super(0)
	move.w	#$20,-(sp)                      ; Super
	trap	#1                              ; Super
	addq.l	#6,sp                           ; drop the arguments
	move.l	d0,saved_ssp-m_keyirq           ; old supervisor stack
	move.l	d0,-(sp)                        ; for the Super call back to user mode
	bsr.s	install_system_vectors          ; install the system vectors
	move.w	#$20,-(sp)                      ; back to user mode
	trap	#1                              ; Super
	addq.l	#6,sp                           ; drop the arguments
	dc.w	$41f9,$0000,$0000               ; lea $0,a0 -> IRQPATCH (filled in by the linker), between-statement
                                                ;   call ...
	move.w	#$4ef9,(a0)+                    ; ... becomes jmp to the event handler
	dc.w	$20fc,$0000,$0000               ; move.l	#$0,(a0)+ -> IRQCHK (filled in by the linker)
.done:
	rts                                     ; done

; Supervisor stack pointer saved when the hooks are installed; used to get back to user mode after an exception.
saved_ssp:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Supervisor part of the install: hooks etv_critic and etv_timer (old handlers kept in the jmp/jsr of the hooks), sets
; conterm bit 3 so keys come with the shift state, and patches the kbshift address for TOS after 1.00.
;------------------------------------------------------------------------------
install_system_vectors:
	lea	$404.w,a0                       ; etv_critic
	move.l	(a0),old_critical_error+2-m_keyirq ; old critical error handler into the jmp
	move.l	#critical_error_hook-m_keyirq,(a0)+ ; our critical error hook
	bset	#$3,$484.w                      ; conterm, keys come with the kbshift state
	movea.l	$4f2.w,a0                       ; _sysbase
	cmpi.w	#$100,2(a0)                     ; TOS 1.00?
	beq.s	.hook_timer                     ; TOS 1.00: keep the built-in address
	move.w	$26(a0),check_break_keys+2-m_keyirq ; later TOS: kbshift pointer into the break check
.hook_timer:
	lea	$400.w,a0                       ; etv_timer
	lea	timer_hook(pc),a1               ; our timer hook
	cmpa.l	(a0),a1                         ; already hooked?
	beq.s	.done                           ; yes: do not hook it twice
	move.l	(a0),6(a1)                      ; old handler into the jsr
	move.l	a1,(a0)                         ; install it
.done:
	rts                                     ; done

;------------------------------------------------------------------------------
; Called at program exit: puts back the ikbdsys vector, restores the system vectors in supervisor mode, makes the
; between-statement call an rts again, and points the exit call at an rts so this runs only once.
;------------------------------------------------------------------------------
remove_keyboard_hooks:
	move.w	#$22,-(sp)                      ; Kbdvbase
	trap	#14                             ; Kbdvbase
	addq.l	#2,sp                           ; drop the argument
	movea.l	d0,a0                           ; Kbdvbase
	move.l	ikbd_hook+2-m_keyirq,d0         ; old ikbdsys handler
	beq.s	.disarm                         ; never installed
	move.l	d0,$20(a0)                      ; put it back
	pea	restore_system_vectors(pc)      ; restore the vectors
	move.w	#$26,-(sp)                      ; Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the arguments
	dc.w	$33fc,$4e75,$0000,$0000         ; move.w #$4e75,$0 -> IRQPATCH (filled in by the linker),
                                                ;   between-statement call becomes rts
.disarm:
	dc.w	$23fc,$0000,$02f6,$0000,$0000   ; move.l #hooks_removed-m_keyirq,$0 -> ExitAdr (filled in by the
                                                ;   linker), exit call now does nothing

;------------------------------------------------------------------------------
; Empty routine the exit call is pointed at after the hooks are removed.
;------------------------------------------------------------------------------
hooks_removed:
	rts                                     ; nothing to do

;------------------------------------------------------------------------------
; BOMBON: catches the processor exceptions 2 to 9 so they raise runtime errors 102 to 109 instead of crashing.\nExit: d0
; changed
;------------------------------------------------------------------------------
BOMBON:
	pea	install_exception_handlers(pc)  ; entry (no label): install the exception handlers in supervisor mode
	move.w	#$26,-(sp)                      ; ... with Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the arguments
	rts                                     ; done

;------------------------------------------------------------------------------
; Supervisor routine: for the vectors 2 to 9 (bus error to trace) whose top byte is not zero, saves the vector and
; points it at its exception stub.
;------------------------------------------------------------------------------
install_exception_handlers:
	moveq	#7,d0                           ; not used
	lea	$8.w,a0                         ; bus error vector, first vector: bus error
	lea	$280,a1                         ; saved vectors
	lea	exception_stubs-m_keyirq,a2     ; first stub
	moveq	#7,d1                           ; 8 vectors: 2 to 9
.next_vector:
	tst.b	(a0)                            ; top byte zero: leave it
	beq.s	.skip                           ; not a RAM address: leave it
	move.l	(a0),(a1)                       ; save the old vector
	move.l	a2,(a0)                         ; our stub
.skip:
	addq.l	#4,a0                           ; next vector
	addq.l	#4,a1                           ; next save slot
	addq.l	#6,a2                           ; stubs are 6 bytes apart
	dbra	d1,.next_vector                 ; all 8
	rts                                     ; done

;------------------------------------------------------------------------------
; Supervisor routine: puts back the saved exception vectors and etv_critic, clears conterm bit 3 and unhooks etv_timer
; if our hook is still first.
;------------------------------------------------------------------------------
restore_system_vectors:
	lea	$280,a0                         ; saved vectors
	lea	$8.w,a1                         ; bus error vector
	moveq	#7,d1                           ; 8 vectors
.next_vector:
	move.l	(a0)+,d0                        ; saved vector
	beq.s	.skip                           ; never replaced
	move.l	d0,(a1)                         ; put it back
.skip:
	addq.l	#4,a1                           ; next vector
	dbra	d1,.next_vector                 ; all 8
	move.l	old_critical_error+2(pc),$404.w ; etv_critic, old critical error handler
	bclr	#$3,$484.w                      ; conterm, keys without the shift state again
	lea	$400.w,a0                       ; etv_timer
	lea	timer_hook(pc),a1               ; our timer hook
	cmpa.l	(a0),a1                         ; still our hook?
	bne.s	.done                           ; not ours: leave it
	move.l	6(a1),(a0)                      ; old handler back
.done:
	rts                                     ; done

;------------------------------------------------------------------------------
; Exception handlers for vectors 2 to 9, six bytes each: push the vector number and go to the common part, which fills
; the TOS crash area ($380-$3ff) like TOS does, returns to user mode on the saved stack and raises runtime error 100 +
; vector number (102 bus error, 103 address error, ...).
;------------------------------------------------------------------------------
exception_stubs:
	pea	$2.w                            ; bus error
	bra.s	.crash                          ; to the common part
	pea	$3.w                            ; address error
	bra.s	.crash                          ; to the common part
	pea	$4.w                            ; illegal instruction
	bra.s	.crash                          ; to the common part
	pea	$5.w                            ; divide by zero
	bra.s	.crash                          ; to the common part
	pea	$6.w                            ; CHK
	bra.s	.crash                          ; to the common part
	pea	$7.w                            ; TRAPV
	bra.s	.crash                          ; to the common part
	pea	$8.w                            ; bus error vector, privilege violation
	bra.s	.crash                          ; to the common part
	pea	$9.w                            ; trace
.crash:
	move.l	#$12345678,$380.w               ; proc_lives, crash area valid
	movem.l	d0-d7/a0-sp,$384.w              ; proc_dregs, all registers
	move.l	(sp)+,d0                        ; vector number
	lea	$3c4.w,a0                       ; proc_enum
	move.w	d0,exception_vector-m_keyirq    ; keep it for the error number
	ror.l	#8,d0                           ; number in the top byte
	move.l	d0,(a0)+                        ; proc_enum: vector number in the top byte
	move.l	usp,a1                          ; user stack pointer
	move.l	a1,(a0)+                        ; proc_usp
	movem.l	(sp),d0-d7                      ; exception frame
	movem.l	d0-d7,(a0)                      ; proc_stk: 16 words of the exception frame
	dc.w	$4df9,$0000,$0000               ; lea	$0,a6 -> BssA6 (filled in by the linker), the runtime block
	lea	$3a90(a6),sp                    ; runtime stack
	andi.w	#$f3ff,sr                       ; lower the interrupt mask
	move.w	#$1,$452.w                      ; vblsem, VBL routines allowed again
	move.l	saved_ssp-m_keyirq,-(sp)        ; supervisor stack from the install
	move.w	#$20,-(sp)                      ; back to user mode
	trap	#1                              ; Super
	lea	$3a90(a6),sp                    ; fresh runtime stack in user mode
	moveq	#100,d0                         ; error 100 + vector number
	add.w	exception_vector(pc),d0         ; plus the vector number

keyirq36_raise_exception_error:
	dc.w	$6000,$0000                     ; bra.w keyirq36_raise_exception_error+2 -> ERROR (filled in by the
                                                ;   linker)

; Vector number of the last exception caught.
exception_vector:
	dc.w	$0000

;------------------------------------------------------------------------------
; etv_critic handler: runs the runtime's GEM hook with a6 set, then goes on to the previous handler.
;------------------------------------------------------------------------------
critical_error_hook:
	move.l	a6,-(sp)                        ; keep a6
	dc.w	$4df9,$0000,$0000               ; lea	$0,a6 -> BssA6 (filled in by the linker), the runtime block

keyirq36_call_qshowm:
