m_exec:
;------------------------------------------------------------------------------
; EXEC mode,name$,cmd$,env$: Pexec. The three strings are copied, each followed by two zero bytes, into the\nbuffer at
; intin; the environment string is cut at 2000 bytes.\nEntry: d1.w = mode, a0 = environment string, a1 = command line,
; d2 = file name (descriptors)\nExit: d0.l = Pexec result; the break flag is cleared
;------------------------------------------------------------------------------
EXEC:
	lea	-$c(sp),sp                      ; room for the three Pexec pointers
	move.w	d1,-(sp)                        ; Pexec mode
	move.l	d2,-(sp)                        ; keep the file name descriptor
	move.l	a1,-(sp)                        ; keep the command line descriptor
	lea	$6a8(a6),a1                     ; buffer for the strings
	move.w	#$7d0,d2                        ; environment: at most 2000 bytes
	bsr.s	exec36_copy_string              ; copy the environment
	move.l	a2,$12(sp)                      ; Pexec environment pointer
	movea.l	(sp)+,a0                        ; command line descriptor
	moveq	#-56,d2                         ; no real limit for the other two
	bsr.s	exec36_copy_string              ; copy the command line
	move.l	a2,$a(sp)                       ; Pexec command line pointer
	movea.l	(sp)+,a0                        ; file name descriptor
	bsr.s	exec36_copy_string              ; copy the file name
	move.l	a2,2(sp)                        ; Pexec file name pointer

exec36_show_mouse:
