;==============================================================================
	dc.b	$44,$49,$4d,$2e,$4f,$00,$00,$00,$00,$00,$00,$00,$00,$00	; library entry: the name DIM.O
	dc.w	$90b6,$1683,$0000,$01b6,$0000,$05a6,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$286,$0,$0,$7e		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_dim:
;------------------------------------------------------------------------------
; DIM of a string array ($): 6-byte descriptors per element.
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_string_array:
	lea	$fffffffe.w,a1                  ; string: 6 bytes per element
	bra.s	dim_array                       ; build the array

;------------------------------------------------------------------------------
; DIM of a boolean array (!): one bit per element.
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_boolean_array:
	lea	$ffffffff.w,a1                  ; boolean: one bit per element
	bra.s	dim_array                       ; build the array

;------------------------------------------------------------------------------
; DIM of a byte array (|).
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_byte_array:
	suba.l	a1,a1                           ; byte
	bra.s	dim_array                       ; build the array

;------------------------------------------------------------------------------
; DIM of a word array (&). The entry at $1acf4 (no label) is DIM of a float array (#), 8 bytes per element.
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_word_array:
	lea	$1.w,a1                         ; word
	bra.s	dim_array                       ; build the array

;------------------------------------------------------------------------------
; DIM of a float array (#): 8 bytes per element.\nEntry: a0 = array descriptor, d7 = number of dimensions, d0 = last
; upper bound, d1-d6 = the other bounds.\nExit: as dim_array.
;------------------------------------------------------------------------------
DIMF:
	lea	$3.w,a1                         ; float: 8 bytes per element
	bra.s	dim_array                       ; build the array

;------------------------------------------------------------------------------
; DIM of a long integer array (%).
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_long_array:
	lea	$2.w,a1                         ; long

;------------------------------------------------------------------------------
; DIM: makes room at the end of the array area, then builds the array block: owner pointer, size, the bounds, and the
; elements cleared to zero. Without OPTION BASE 1 every bound gets one extra element. A dimension above 65535 elements
; or a block that would overflow is error 8; an array already dimensioned is an error.
; Entry: a0 = array descriptor, a1 = element size code (-2 string, -1 bit, 0 byte, 1 word, 2 long, 3 float), d7 = number
; of dimensions, d0 = last bound, d1-d6 = the other bounds.
; Exit: descriptor points at the bounds, its word at 4 = number of dimensions.
;------------------------------------------------------------------------------
dim_array:
	move.l	a3,$20(a6)                      ; keep the heap top
	tst.w	4(a0)                           ; already dimensioned?
	bne.w	dim36_raise_bound_error         ; yes: error
	tst.l	$e(a6)                          ; OPTION BASE 1?
	bne.s	.collect_bounds                 ; yes: bounds are element counts
	addq.l	#1,d0                           ; bounds count from 0: one more element each
	addq.l	#1,d1                           ; for every dimension
	addq.l	#1,d2
	addq.l	#1,d3
	addq.l	#1,d4
	addq.l	#1,d5
	addq.l	#1,d6
.collect_bounds:
	pea	(a0)                            ; keep the descriptor
	move.w	a1,-(sp)                        ; element size code
	exg	d7,d0                           ; d7 = last bound, d0 = number of dimensions
	lea	$4a(a6),a1                      ; bounds go into the line buffer
	movem.l	d1-d6,(a1)                      ; the other bounds
	move.w	d0,d4                           ; d4 = number of dimensions
	move.w	d4,d5                           ; offset of the last bound's slot
	asl.w	#2,d5                           ; 4 bytes per bound
	move.l	d7,-$4(a1,d5.w)                 ; last bound into its slot
	move.l	#$ffff,d3                       ; largest dimension
	move.w	(sp),d1                         ; size code
	move.l	(a1)+,d0                        ; first dimension
	bra.s	.next_bound                     ; multiply them all
.multiply:
	cmp.l	d3,d0                           ; dimension too large?
	bhi.w	dim36_raise_bound_error         ; yes: error
	move.l	(a1)+,d2                        ; next dimension
	cmp.l	d3,d2                           ; too large?
	bhi.w	dim36_raise_bound_error         ; yes: error
	mulu.w	d2,d0                           ; total elements
.next_bound:
	subq.w	#4,d5                           ; one bound fewer
	bne.s	.multiply                       ; more dimensions
	bra.s	dim36_scale_size                ; elements to bytes

dim36_bits_or_strings:
	addq.w	#1,d1                           ; bits?
	bne.s	.string_elements                ; no: strings
	moveq	#15,d1                          ; flags: whole words of 16 bits
	add.l	d1,d0                           ; round up to 16 bits
	lsr.l	#4,d0                           ; words
	add.l	d0,d0                           ; bytes
	bra.s	dim36_add_header                ; add the header
.string_elements:
	add.l	d0,d0                           ; strings: elements * 6
	bcs.s	dim36_too_big                   ; overflow
	move.l	d0,d1                           ; elements * 2
	add.l	d0,d0                           ; elements * 4
	bcs.s	dim36_too_big                   ; overflow
	add.l	d1,d0                           ; elements * 6
	bcc.s	dim36_add_header                ; no overflow: add the header

dim36_too_big:
	moveq	#8,d0                           ; error 8

dim36_raise_error:
	dc.w	$6000,$0000                     ; bra.w	dim36_raise_error+2 -> ERROR (filled in by the linker)

dim36_scale_size:
	tst.w	d1                              ; negative size code: bits or strings
	bmi.s	dim36_bits_or_strings           ; yes
	bne.s	.shift_size                     ; not bytes
	btst	#$0,d0                          ; bytes: round up to an even count
	beq.s	.shift_size                     ; even already
	addq.l	#1,d0                           ; one byte more
.shift_size:
	asl.l	d1,d0                           ; elements << size code
	bcs.s	dim36_too_big                   ; overflow

dim36_add_header:
	moveq	#8,d1                           ; header: owner, size and 4 bytes per bound
	move.w	d4,-(sp)                        ; keep the number of dimensions
	asl.w	#2,d4                           ; 4 bytes per bound
	add.w	d4,d1                           ; header size
	add.l	d1,d0                           ; block size
	bsr.w	open_array_gap                  ; make room at the end of the array area
	lea	$1c(a6),a0                      ; allocate the block at the end of the arrays

dim36_allot_block:
	dc.w	$6100,$0000                     ; bsr.w	dim36_allot_block+2 -> ALLOT (filled in by the linker)
	move.w	(sp)+,d4                        ; number of dimensions
	movea.l	a0,a2                           ; block start
	addq.l	#4,a0                           ; skip the owner slot
	move.l	d0,(a0)+                        ; block size
	move.w	d4,d5                           ; offset of the last bound
	lea	$4a(a6),a1                      ; bounds, copied last first
	asl.w	#2,d5                           ; 4 bytes per bound
	adda.w	d5,a1                           ; past the last bound
	bra.s	.next_copy                      ; copy them
.copy_bound:
	move.l	-(a1),(a0)+                     ; next bound
.next_copy:
	subq.w	#4,d5                           ; one bound fewer
	bpl.s	.copy_bound                     ; more bounds
	addq.l	#2,sp                           ; drop the size code
	movea.l	(sp)+,a1                        ; the descriptor
	move.l	a1,(a2)                         ; block owner
	addq.l	#8,a2                           ; descriptor points at the bounds
	move.l	a2,(a1)+                        ; descriptor -> first bound
	move.w	d4,(a1)+                        ; number of dimensions
	moveq	#0,d2                           ; clear the elements
	moveq	#8,d1                           ; header size
	asl.w	#2,d4                           ; 4 bytes per bound
	add.w	d4,d1                           ; plus owner and size
	sub.l	d1,d0                           ; bytes to clear
	lsr.l	#2,d0                           ; an odd word?
	bcc.s	.clear_long                     ; no
	move.w	d2,(a0)+                        ; clear a word
.clear_long:
	lsr.l	#1,d0                           ; an odd long?
	bcc.s	.clear_two_longs                ; no
	move.l	d2,(a0)+                        ; clear a long
.clear_two_longs:
	lsr.l	#1,d0                           ; two more longs?
	bcc.s	.clear_blocks                   ; no
	move.l	d2,(a0)+                        ; clear two longs
	move.l	d2,(a0)+
.clear_blocks:
	lsr.l	#1,d0                           ; count of 32-byte blocks
	bcc.s	.next_block                     ; none odd
	bra.s	.clear_eight_longs              ; into the middle of the loop
.clear_four_longs:
	move.l	d2,(a0)+                        ; clear 32 bytes per pass
	move.l	d2,(a0)+
	move.l	d2,(a0)+
	move.l	d2,(a0)+
.clear_eight_longs:
	move.l	d2,(a0)+                        ; second half of the pass
	move.l	d2,(a0)+
	move.l	d2,(a0)+
	move.l	d2,(a0)+
.next_block:
	dbra	d0,.clear_four_longs            ; dbra counts only 16 bits
	subi.l	#$10000,d0                      ; high word of the count
	bpl.s	.clear_four_longs               ; more passes
	rts                                     ; done

dim36_raise_bound_error:
	dc.w	$6000,$0000                     ; bra.w dim36_raise_bound_error+2 -> ERROR (filled in by the linker),
                                                ;   error exit

;------------------------------------------------------------------------------
; Drops the strings owned by an array block that is being removed, then moves the pointers into the array area down by
; the block size.
; Entry: a0 = block start, d0 = block size.
;------------------------------------------------------------------------------
release_array_strings:
	bsr.w	collect_strings_except          ; drop its strings, fix descriptors above it
	neg.l	d0                              ; the pointers move down
	bsr.s	move_array_pointers             ; fix pointers in the array area
	neg.l	d0                              ; size positive again
	rts                                     ; done

;------------------------------------------------------------------------------
; Makes room for d0 bytes at the end of the array area: moves the string descriptors and the temporary data above it up
; by d0.
; Entry: d0 = size.
;------------------------------------------------------------------------------
open_array_gap:
	movea.l	$1c(a6),a0                      ; end of the arrays
	bsr.s	collect_strings                 ; move the strings above it

;------------------------------------------------------------------------------
; Walks the temporary data from the heap top down to the end of the arrays and adds d0 to every pointer that points into
; the moved part.
; Entry: d0 = distance, a3 = heap top.
; Exit: a3 reloaded from the saved heap top.
;------------------------------------------------------------------------------
move_array_pointers:
	movea.l	a3,a0                           ; from the heap top
	movea.l	$1c(a6),a1                      ; down to the end of the arrays
.check_done:
	cmpa.l	a0,a1                           ; all entries done?
	beq.s	.done                           ; yes
.next_entry:
	move.w	-(a0),d1                        ; entry length
	movea.l	-(a0),a2                        ; entry owner
	beq.s	.check_done                     ; zero: nothing to fix
	bmi.s	.special_entry                  ; negative: special entry
	movea.l	a0,a3                           ; entry start
	suba.w	d1,a3                           ; minus its length
	cmpa.l	(a2),a3                         ; owner points at it?
	beq.s	.move_owner                     ; yes: move the owner pointer
	cmpi.w	#$4,d1                          ; a long entry ...
	bne.s	.check_pointer                  ; no
	cmpa.l	(a2),a1                         ; ... whose owner is in the moved part
	bcc.s	.check_pointer                  ; no
	cmpa.l	(a2),a0                         ; owner above this entry?
	bcs.s	.check_pointer                  ; no
.move_owner:
	add.l	d0,(a2)                         ; owner follows the move
.check_pointer:
	movea.l	-(a0),a2                        ; pointer kept in the entry
	cmpa.l	a1,a2                           ; below the moved part
	bcs.s	.skip_entry                     ; yes: leave it
	cmpa.l	a0,a2                           ; above this entry
	bhi.s	.skip_entry                     ; yes: leave it
	add.l	d0,(a0)                         ; follows the move
.skip_entry:
	suba.w	d1,a0                           ; to the next entry
	addq.l	#4,a0                           ; past the owner and length
	cmpa.l	a0,a1                           ; reached the end of the arrays?
	bne.s	.next_entry                     ; no: next entry
.done:
	movea.l	$20(a6),a3                      ; heap top back
	rts                                     ; done
.special_entry:
	cmpi.w	#$ffff,d1                       ; -1: a block of its own length
	beq.s	.skip_block                     ; skip a whole block
	cmpa.l	a1,a2                           ; pointer in the moved part?
	bcs.s	.skip_special                   ; no
	cmpa.l	a0,a2                           ; above this entry?
	bhi.s	.skip_special                   ; yes: leave it
	add.l	d0,(a0)                         ; pointer follows the move
.skip_special:
	lea	4(a0,d1.w),a0                   ; to the next entry
	bra.s	.check_done                     ; next entry
.skip_block:
	suba.l	a2,a0                           ; skip the block
	bra.s	.check_done                     ; next entry

;------------------------------------------------------------------------------
; Garbage collection of the string space: moves every used string to the top, drops free blocks, updates the string
; descriptors and adds d0 to descriptors that lie above a0 (in the moved array area).
; Entry: a0 = limit, d0 = distance.
; Exit: new bottom of the string space set, a3 reloaded.
;------------------------------------------------------------------------------
collect_strings:
	move.l	a3,$20(a6)                      ; keep the heap top
	moveq	#-2,d4                          ; mask to round lengths up to even
	move.l	a0,d2                           ; limit
	movea.l	$28(a6),a0                      ; top of the string space
	movea.l	$24(a6),a2                      ; bottom of the string space
.next_string:
	movea.l	a0,a1                           ; moving starts here
	cmpa.l	a0,a2                           ; whole string space done?
	beq.s	.done                           ; yes
	move.l	-(a0),d1                        ; owner descriptor of the string below
	movea.l	d1,a3                           ; a3 = its descriptor
	bmi.s	.free_block                     ; negative: free block
	cmp.l	d2,d1                           ; descriptor above the limit ...
	bls.s	.to_next                        ; no: leave it
	cmp.l	$28(a6),d1                      ; ... and inside the heap: move it
	bhi.s	.to_next                        ; no: leave it
	add.l	d0,(a0)                         ; back pointer follows the move
.to_next:
	movea.l	(a3),a0                         ; descriptor text pointer: next string down
	bra.s	.next_string                    ; next string
.free_block:
	adda.l	d1,a0                           ; skip the free block
	cmpa.l	a0,a2                           ; reached the bottom?
	beq.s	.done                           ; yes
.move_string:
	move.l	-(a0),d1                        ; next owner
	bmi.s	.free_block                     ; free: skip it too
	move.l	d1,-(a1)                        ; copied up
	movea.l	d1,a3                           ; a3 = its descriptor
	cmp.l	d2,d1                           ; descriptor above the limit ...
	bls.s	.copy_text                      ; no
	cmp.l	$28(a6),d1                      ; ... and inside the heap?
	bhi.s	.copy_text                      ; no
	add.l	d0,(a1)                         ; back pointer follows the move
.copy_text:
	move.w	4(a3),d1                        ; text length
	subq.w	#1,d1                           ; in words
	lsr.w	#1,d1                           ; round up
.copy_word:
	move.w	-(a0),-(a1)                     ; move the text up
	dbra	d1,.copy_word                   ; next word
	move.l	a1,(a3)                         ; descriptor follows the text
	cmpa.l	a0,a2                           ; reached the bottom?
	bne.s	.move_string                    ; no: next string
.done:
	move.l	a1,$24(a6)                      ; new bottom of the string space
	movea.l	$20(a6),a3                      ; heap top back
	rts                                     ; done

;------------------------------------------------------------------------------
; Like collect_strings, but strings owned by descriptors inside the block a0 to a0+d0 (an array being removed) are
; dropped and descriptors above the block are moved down by d0.
; Entry: a0 = block start, d0 = block size.
;------------------------------------------------------------------------------
collect_strings_except:
	move.l	a3,$20(a6)                      ; keep the heap top
	moveq	#-2,d4                          ; mask to round lengths up to even
	move.l	a0,d2                           ; start of the block
	move.l	d2,d3                           ; end of the block
	add.l	d0,d3                           ; block end = start + size
	movea.l	$28(a6),a0                      ; top of the string space
	movea.l	$24(a6),a2                      ; bottom of the string space
.next_string:
	movea.l	a0,a1                           ; moving starts here
	cmpa.l	a0,a2                           ; whole string space done?
	beq.s	.done                           ; yes
	move.l	-(a0),d1                        ; owner descriptor of the string below
	bmi.s	.free_block                     ; negative: free block
	movea.l	d1,a3                           ; a3 = its descriptor
	cmp.l	d2,d1                           ; descriptor below the block or outside the heap: keep
	bls.s	.to_next                        ; keep it
	cmp.l	$28(a6),d1                      ; outside the heap?
	bhi.s	.to_next                        ; yes: keep it
	cmp.l	d3,d1                           ; inside the block: the string is dropped
	bhi.s	.move_owner                     ; above the block
	movea.l	(a3),a0                         ; to the next string down
	bra.s	.check_done                     ; dropped
.move_owner:
	sub.l	d0,(a0)                         ; above the block: moves down
.to_next:
	movea.l	(a3),a0                         ; descriptor text pointer: next string down
	bra.s	.next_string                    ; next string
.free_block:
	adda.l	d1,a0                           ; skip the free block
.check_done:
	cmpa.l	a0,a2                           ; reached the bottom?
	beq.s	.done                           ; yes
.next_owner:
	move.l	-(a0),d1                        ; next owner
	bmi.s	.free_block                     ; free: skip it
	move.l	d1,-(a1)                        ; copied up
	movea.l	d1,a3                           ; a3 = its descriptor
	cmp.l	d2,d1                           ; below the block?
	bls.s	.copy_text                      ; below the block: keep
	cmp.l	$28(a6),d1                      ; outside the heap?
	bhi.s	.copy_text                      ; yes: keep it
	cmp.l	d3,d1                           ; inside the block ...
	bhi.s	.owner_down                     ; no: above the block
	moveq	#1,d1                           ; ... skip its text
	add.w	4(a3),d1                        ; plus the text length
	and.b	d4,d1                           ; rounded up to even
	suba.l	d1,a0                           ; skip the text
	addq.l	#4,a1                           ; and its owner slot
	bra.s	.check_done                     ; next string
.owner_down:
	sub.l	d0,(a1)                         ; above the block: moves down
.copy_text:
	move.w	4(a3),d1                        ; text length in words
	subq.w	#1,d1                           ; round up
	lsr.w	#1,d1                           ; in words
.copy_word:
	move.w	-(a0),-(a1)                     ; move the text up
	dbra	d1,.copy_word                   ; next word
	move.l	a1,(a3)                         ; descriptor follows the text
	cmpa.l	a0,a2                           ; reached the bottom?
	bne.s	.next_owner                     ; no: next string
.done:
	move.l	a1,$24(a6)                      ; new bottom of the string space
	movea.l	$20(a6),a3                      ; heap top back
	rts                                     ; done

