	add.l	(a3)+,d3
	add.l	(a3)+,d3
	add.l	(a3)+,d3
	add.l	(a3)+,d3
	move.l	d3,d4                           ; high word of the total ...
	swap	d4
	add.w	d4,d3                           ; ... added to the low word
	asl.w	#2,d3                           ; 4 bytes each
	adda.w	d3,a1                           ; past them
	clr.w	-(sp)                           ; pass flag
.next_pass:
