	asl.w	#3,d3                           ; 8 bytes each
	adda.w	d3,a1                           ; past them
	moveq	#6,d3                           ; 6 bytes each (string descriptors)
	mulu.w	(a3)+,d3                        ; times the count
	adda.w	d3,a1                           ; past them
	move.w	(a3)+,d3                        ; next count
	asl.w	#2,d3                           ; times 4
	add.w	(a3)+,d3                        ; plus another count
	addq.w	#1,d3                           ; rounded up to even
	and.w	d6,d3
	adda.w	d3,a1                           ; past them
	move.w	(a3)+,d4                        ; array descriptors of the first kinds
	add.w	(a3)+,d4                        ; plus the other counts
