	add.w	d3,d3                           ; times 2
	add.w	(a3)+,d3                        ; plus another count
	addq.w	#1,d3                           ; rounded up to even
	and.w	d6,d3
	adda.w	d3,a1                           ; past them
	move.w	(a3)+,d4                        ; array descriptors of the other kinds
	add.w	(a3)+,d4                        ; plus the next count
	bsr.s	fix_array_descriptors           ; fix them
