	movem.w	$1264(a6),a0-a1                 ; graphics origin x and y
	add.w	a0,d1                           ; every point plus the origin
	add.w	a1,d2                           ; y0 + origin y
	add.w	a0,d3                           ; x1
	add.w	a1,d4                           ; y1
	add.w	a0,d5                           ; x2
	add.w	a1,d6                           ; y2
	add.w	a0,d7                           ; x3
	add.w	a1,d0                           ; y3
