	move.l	d2,(a2)                         ; y0 ...
	move.w	d1,(a2)                         ; ... and x0: P0 as one long
	movea.l	(a2),a0                         ; a0 = P0 as one long
	lea	$7a8(a6),a1                     ; ptsin[0]
.fill_start:
	move.l	a0,-(a2)                        ; every point starts as P0
	cmpa.l	a1,a2                           ; down to ptsin[0]
	bhi.s	.fill_start                     ; more points
	lea	$7ac(a6),a2                     ; point 1: the first one worked out
	sub.w	d3,d5                           ; x2 - x1
	sub.w	d1,d3                           ; x1 - x0
	muls.w	#$3,d3                          ; cx = 3(x1 - x0)
	muls.w	#$3,d5                          ; 3(x2 - x1)
	sub.l	d3,d5                           ; bx = 3(x2 - x1) - cx
	sub.w	d1,d7                           ; x3 - x0
	ext.l	d7                              ; as a long
	sub.l	d3,d7                           ; minus cx
	sub.l	d5,d7                           ; ax = x3 - x0 - cx - bx
	sub.w	d4,d6                           ; y2 - y1
	sub.w	d2,d4                           ; y1 - y0
	muls.w	#$3,d4                          ; cy = 3(y1 - y0)
	muls.w	#$3,d6                          ; 3(y2 - y1)
	sub.l	d4,d6                           ; by = 3(y2 - y1) - cy
	sub.w	d2,d0                           ; y3 - y0
	ext.l	d0                              ; as a long
	sub.l	d4,d0                           ; minus cy
	sub.l	d6,d0                           ; ay = y3 - y0 - cy - by
	asl.l	#5,d5                           ; bx * 32
	asl.l	#5,d6                           ; by * 32
	asl.l	#8,d3                           ; cx * 1024
	asl.l	#2,d3
	asl.l	#8,d4                           ; cy * 1024
	asl.l	#2,d4
	suba.l	a1,a1                           ; i = 0
.next_point:
	move.l	d5,d1                           ; x: Horner with n = i + 1
	move.w	a1,d2
.x_cubic:
	add.l	d7,d1                           ; 32 bx + ax * n
	dbra	d2,.x_cubic
	move.w	a1,d2                           ; n again
	movea.l	d1,a0                           ; keep the value
