	dc.w	$303a,$0002                     ; move.w matdet36_whole_offset(pc),d0 -> MatOffse (filled in by the
                                                ;   linker)

matdet36_whole_offset:
	sub.w	d0,d2                           ; size = bound - MAT offset
	move.w	d0,d1                           ; both starts = MAT offset
	bra.s	matdet36_copy

matdet36_sub_matrix:
	move.w	d5,d0                           ; start indexes
	move.w	d6,d1
	move.w	d4,d2                           ; size

matdet36_copy:
	movem.w	d0-d2,$2c(sp)                   ; starts and size
	move.w	d2,d0                           ; n
	mulu.w	d0,d0                           ; n * n
	asl.l	#3,d0                           ; 8 bytes per element
	bsr.w	matdet36_alloc_scratch          ; room for the copy
	movea.l	a0,a2                           ; a2 = copy
	subq.w	#1,d2                           ; n - 1
	move.w	d2,d1                           ; runs to copy
	move.l	a1,d7                           ; array data
.next_run:
	move.w	$2e(sp),d3                      ; run index * d1 bound ...
	mulu.w	$20(sp),d3
	move.w	$2c(sp),d0                      ; ... + start index
	ext.l	d0
	add.l	d0,d3
	asl.l	#3,d3                           ; 8 bytes per element
	add.l	d7,d3                           ; in the array
	movea.l	d3,a1
	move.w	d2,d0                           ; n elements
.copy_element:
	move.l	(a1)+,(a0)+                     ; copy one element
	move.l	(a1)+,(a0)+
	dbra	d0,.copy_element
	addq.w	#1,$2e(sp)                      ; next run
	dbra	d1,.next_run                    ; more runs
	move.w	d2,$22(sp)                      ; n - 1
	addq.w	#1,d2                           ; n
	move.w	d2,$20(sp)
	tst.b	$50(sp)                         ; rank?
	bgt.s	.eliminate                      ; yes: always eliminate
	subq.w	#2,d2                           ; n = 1?
	bmi.w	matdet36_one                    ; yes: the element itself
	beq.w	matdet36_two                    ; n = 2: direct formula
	subq.w	#1,d2                           ; n = 3?
	beq.w	matdet36_three                  ; yes: Sarrus rule
.eliminate:
	clr.w	$4a(sp)                         ; no row or column swaps yet
	clr.w	$32(sp)                         ; step k = 0
	clr.l	$34(sp)                         ; offset of row k = 0
	move.w	$20(sp),d2                      ; row size = n * 8
	ext.l	d2
	asl.l	#3,d2
	move.l	d2,$38(sp)

matdet36_step:
	move.w	$32(sp),$40(sp)                 ; row of the pivot
	move.w	$32(sp),d4                      ; diagonal element k,k
	ext.l	d4
	asl.l	#3,d4                           ; 8 bytes per element
	add.l	$34(sp),d4
	lea	0(a2,d4.l),a1
	movem.l	(a1),d0-d1                      ; pivot candidate
	movem.l	d0-d1,(sp)
	tst.w	d1                              ; exponent 0: element is 0
	beq.s	.search_pivot
	tst.b	$50(sp)                         ; quick determinant?
	bmi.w	.check_pivot                    ; yes: use the diagonal element
.search_pivot:
	addq.l	#8,a1                           ; next element
	move.l	d1,d2                           ; d0:d1.w mantissa, d2 exponent
	swap	d1
	move.w	$32(sp),d7                      ; start the scan at k
	move.w	d7,$42(sp)                      ; column index
	move.w	d7,$44(sp)                      ; row index
	move.w	d7,$46(sp)                      ; best column
	move.w	d7,$48(sp)                      ; best row
	bra.s	.next_element                   ; into the loop
.compare:
	move.l	(a1)+,d3                        ; element
	move.w	(a1)+,d4
	move.w	(a1)+,d5
	move.w	d2,d6                           ; |best exponent|
	bpl.s	.abs_element
	neg.w	d6
.abs_element:
	move.w	d5,d7                           ; |element exponent|
	bpl.s	.compare_magnitude
	neg.w	d7
.compare_magnitude:
	cmp.w	d6,d7                           ; larger exponent?
	bgt.s	.new_best                       ; yes: new best
	blt.s	.next_element                   ; smaller: keep the best
	cmp.l	d0,d3                           ; same: compare the mantissas
	bcs.s	.next_element                   ; smaller
	bne.s	.new_best                       ; larger
	cmp.w	d1,d4                           ; low words
	bls.s	.next_element                   ; not larger
.new_best:
	move.l	d3,d0                           ; new best element
	move.l	d4,d1
	move.l	d5,d2
	move.w	$42(sp),$46(sp)                 ; its column
	move.w	$44(sp),$48(sp)                 ; and its row
.next_element:
	addq.w	#1,$42(sp)                      ; next column
	move.w	$42(sp),d7
	cmp.w	$20(sp),d7                      ; below n?
	bcs.s	.compare                        ; yes
	move.w	$32(sp),d6                      ; back to column k ...
	move.w	d6,$42(sp)
	ext.l	d6
	asl.l	#3,d6                           ; 8 bytes per element
	adda.l	d6,a1                           ; ... of the next row
	addq.w	#1,$44(sp)                      ; next row
	cmp.w	$44(sp),d7                      ; below n?
	bhi.s	.compare                        ; yes
	swap	d1                              ; repack the best element
	move.w	d2,d1
	movem.l	d0-d1,(sp)                      ; pivot
	move.w	$32(sp),d2                      ; step k
	move.w	$46(sp),d3                      ; best column
	cmp.w	d3,d2                           ; already column k?
	beq.s	.check_row_swap                 ; yes
	move.w	$40(sp),d0                      ; swap columns k and best: from row k
	moveq	#0,d1
	move.w	$20(sp),d1                      ; n
	move.w	d0,d5                           ; row index * n
	mulu.w	d1,d5
	ext.l	d2
	ext.l	d3
	asl.l	#3,d3                           ; 8 bytes per element
	asl.l	#3,d2
	asl.l	#3,d5
	move.l	d1,d7                           ; row size
	asl.l	#3,d7
	bra.s	.check_rows                     ; into the loop
.swap_column_element:
	move.l	d2,d4                           ; element k of the row
	add.l	d5,d4
	lea	0(a2,d4.l),a1
	move.l	d3,d4                           ; element best of the row
	add.l	d5,d4
	lea	0(a2,d4.l),a0
	move.l	(a0),d6                         ; swap them
	move.l	(a1),(a0)+
	move.l	d6,(a1)+
	move.l	(a0),d6
	move.l	(a1),(a0)+
	move.l	d6,(a1)+
	addq.w	#1,d0                           ; next row
	add.l	d7,d5
.check_rows:
	cmp.w	d1,d0                           ; all rows?
	bcs.s	.swap_column_element            ; no
	addq.w	#1,$4a(sp)                      ; one swap more: sign changes
.check_row_swap:
	move.w	$40(sp),d0                      ; row k
	cmp.w	$48(sp),d0                      ; the best row?
	beq.s	.check_pivot                    ; yes: no row swap
	move.w	$32(sp),$42(sp)                 ; swap rows k and best from column k
	move.w	$40(sp),d5                      ; row k * n
	move.w	$20(sp),d2
	mulu.w	d2,d5
	move.w	$48(sp),d6                      ; best row * n
	mulu.w	d2,d6
	move.w	$42(sp),d1                      ; column k
	ext.l	d1                              ; 8 bytes per element
	asl.l	#3,d1
	asl.l	#3,d5
	asl.l	#3,d6
	ext.l	d2                              ; row size
	asl.l	#3,d2
	lea	0(a2,d1.l),a0                   ; column k of row 0
	lea	0(a0,d6.l),a1                   ; best row
	adda.l	d5,a0                           ; row k
	bra.s	.check_columns                  ; into the loop
.swap_row_element:
	move.l	(a0),d0                         ; swap one element
	move.l	(a1),(a0)+
	move.l	d0,(a1)+
	move.l	(a0),d0
	move.l	(a1),(a0)+
	move.l	d0,(a1)+
	addq.l	#8,d1                           ; next column
.check_columns:
	cmp.l	d2,d1                           ; end of the row?
	bcs.s	.swap_row_element               ; no
	addq.w	#1,$4a(sp)                      ; one swap more: sign changes
.check_pivot:
	move.w	6(sp),d2                        ; pivot exponent
	beq.w	matdet36_step_done              ; 0: singular, nothing to eliminate
	move.w	$32(sp),$42(sp)                 ; column index from k
	bra.w	matdet36_column_count           ; into the loop

matdet36_next_column:
	move.w	$40(sp),d5                      ; row k ...
	move.w	$42(sp),d4                      ; column j
	ext.l	d4
	mulu.w	$20(sp),d5                      ; ... * n
	add.l	d5,d4
	asl.l	#3,d4                           ; 8 bytes per element
	lea	8(a2,d4.l),a0                   ; element k,j+1
	move.l	(a0)+,d0
	move.w	(a0)+,d1
	move.w	(a0)+,d2
	move.l	(sp),d3                         ; divided by the pivot
	movem.w	4(sp),d4-d5

matdet36_divide_pivot:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_divide_pivot+2 -> FDIV (filled in by the linker)
	movem.l	d0-d2,$c(sp)                    ; factor
	move.w	$40(sp),d0                      ; row index from k
	move.w	d0,$44(sp)
	mulu.w	$20(sp),d0                      ; row * n
	asl.l	#3,d0                           ; 8 bytes per element
	lea	0(a2,d0.l),a1                   ; row start
	bra.s	matdet36_row_count              ; into the loop (row k+1 first)

matdet36_next_row:
	move.w	$32(sp),d4                      ; element i,k
	ext.l	d4
	asl.l	#3,d4                           ; 8 bytes per element
	lea	0(a1,d4.l),a0
	move.l	(a0)+,d0
	move.w	(a0)+,d1
	move.w	(a0)+,d2
	movem.l	$c(sp),d3-d5                    ; times the factor

matdet36_multiply_factor:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_multiply_factor+2 -> FMUL (filled in by the linker)
	move.w	$42(sp),d4                      ; element i,j+1
	ext.l	d4
	asl.l	#3,d4                           ; 8 bytes per element
	lea	8(a1,d4.l),a0
	move.l	(a0)+,d3
	move.w	(a0)+,d4
	move.w	(a0)+,d5
	cmp.w	d2,d5                           ; same exponent ...
	bne.s	.subtract                       ; no: subtract normally
	cmp.l	d0,d3                           ; ... and high mantissa?
	bne.s	.subtract                       ; no: subtract normally
	lsr.w	#8,d1                           ; nearly equal: low words rounded to 8 bits
	bcc.s	.round_element
	addq.w	#1,d1
.round_element:
	lsr.w	#8,d4
	bcc.s	.difference
	addq.w	#1,d4
.difference:
	sub.w	d4,d1                           ; difference of the rounded low words
	beq.s	.zero                           ; equal: the result is 0
	move.w	d2,d3                           ; keep the sign
	bpl.s	.normalise
	neg.w	d2                              ; |exponent|
.normalise:
	subq.w	#1,d2                           ; one bit less ...
	add.w	d1,d1                           ; ... until the top bit is set
	bpl.s	.normalise
	move.w	d1,d0                           ; the difference as the mantissa
	swap	d0
	moveq	#0,d1
	move.w	d1,d0
	tst.w	d3                              ; negative?
	bpl.s	matdet36_store_element          ; no
	neg.w	d2                              ; sign back
	bra.s	matdet36_store_element          ; store it
.zero:
	moveq	#0,d2                           ; exponent 0: the value 0
	bra.s	matdet36_store_element          ; store it
.subtract:
	neg.w	d2                              ; element - product

matdet36_subtract_product:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_subtract_product+2 -> FADD (filled in by the linker)

matdet36_store_element:
	move.w	d2,-(a0)                        ; store the new element
	move.w	d1,-(a0)
	move.l	d0,-(a0)

matdet36_row_count:
	addq.w	#1,$44(sp)                      ; next row
	move.w	$20(sp),d0                      ; row size ...
	ext.l	d0
	asl.l	#3,d0
	adda.l	d0,a1                           ; ... to the next row
	move.w	$44(sp),d0                      ; row index
	cmp.w	$20(sp),d0                      ; below n?
	bcs.w	matdet36_next_row               ; yes
	addq.w	#1,$42(sp)                      ; next column

matdet36_column_count:
	move.w	$42(sp),d0                      ; column index
	cmp.w	$22(sp),d0                      ; below n - 1?
	bcs.w	matdet36_next_column            ; yes

matdet36_step_done:
	addq.w	#1,$32(sp)                      ; next step
	move.l	$38(sp),d0                      ; row size
	add.l	d0,$34(sp)                      ; offset of row k
	move.w	$32(sp),d0                      ; step
	cmp.w	$22(sp),d0                      ; below n - 1?
	bcs.w	matdet36_step                   ; yes
	tst.b	$50(sp)                         ; rank?
	bgt.s	matdet36_rank                   ; yes: count the rank
	move.l	(a2)+,d0                        ; product of the diagonal: element 0,0
	move.w	(a2)+,d1
	move.w	(a2)+,d2
	movea.l	$38(sp),a0                      ; row size
	movea.w	$20(sp),a1                      ; n elements
	lsr.w	$4a(sp)                         ; odd number of swaps?
	bcc.s	matdet36_next_diagonal          ; no
	neg.w	d2                              ; negate
	bra.s	matdet36_next_diagonal

matdet36_multiply_diagonal:
	move.l	(a2)+,d3                        ; next diagonal element
	move.w	(a2)+,d4
	move.w	(a2)+,d5

matdet36_call_fmul:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_call_fmul+2 -> FMUL (filled in by the linker)

matdet36_next_diagonal:
	adda.l	a0,a2                           ; next row: the next diagonal element
	subq.w	#1,a1                           ; one fewer
	move.w	a1,d3
	bgt.s	matdet36_multiply_diagonal      ; more

matdet36_done:
	lea	$52(sp),sp                      ; drop the frame and the mode
	rts                                     ; done

matdet36_rank:
	moveq	#0,d0                           ; rank = 0
	move.w	$20(sp),d1                      ; n diagonal elements
.next_diagonal:
	addq.l	#6,a2                           ; exponent word
	tst.w	(a2)+                           ; 0: element is 0
	beq.s	.skip_row
	addq.w	#1,d0                           ; one more non-zero row
.skip_row:
	adda.l	$38(sp),a2                      ; next diagonal element
	subq.w	#1,d1                           ; one fewer
	bgt.s	.next_diagonal                  ; more

matdet36_rank_to_float:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_rank_to_float+2 -> FITOF (filled in by the linker)
	bra.s	matdet36_done                   ; done

matdet36_one:
	move.l	(a2)+,d0                        ; n = 1: the element itself
	move.w	(a2)+,d1
	move.w	(a2)+,d2
	bra.s	matdet36_done                   ; done

;------------------------------------------------------------------------------
; n = 2: a00*a11 - a01*a10.
;------------------------------------------------------------------------------
matdet36_two:
	lea	matdet36_done(pc),a1            ; return to the end

;------------------------------------------------------------------------------
; Determinant of a 2x2 matrix, also used by MAT INV.\nEntry: a2 = matrix (4 packed elements), a1 = where to go
; afterwards\nExit: d0-d2 = determinant; a2 advanced by 16
;------------------------------------------------------------------------------
matdet36_two_formula:
	movem.l	(a2)+,d0-d1                     ; a00
	movem.l	$10(a2),d3-d4                   ; a11
	bsr.s	matdet36_multiply_packed        ; a00 * a11
	movem.l	d0-d2,(sp)                      ; keep it
	movem.l	(a2)+,d0-d1/d3-d4               ; a01 and a10
	bsr.s	matdet36_multiply_packed        ; a01 * a10
	movem.l	(sp),d3-d5                      ; a00 * a11

matdet36_subtract:
	neg.w	d2                              ; minus the product

matdet36_add_terms:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_add_terms+2 -> FADD (filled in by the linker)
	jmp	(a1)                            ; continue at a1

;------------------------------------------------------------------------------
; Multiplies two packed elements (d0:d1 and d3:d4 as read with movem.l).\nExit: d0-d2 = product
;------------------------------------------------------------------------------
matdet36_multiply_packed:
	move.w	d1,d2                           ; exponent of the first
	swap	d1                              ; mantissa low word

;------------------------------------------------------------------------------
; Multiplies d0-d2 by the packed element d3:d4.\nExit: d0-d2 = product
;------------------------------------------------------------------------------
matdet36_multiply_by_packed:
	move.w	d4,d5                           ; exponent of the second
	swap	d4                              ; mantissa low word

matdet36_tail_fmul:
	dc.w	$6000,$0000                     ; bra.w	matdet36_tail_fmul+2 -> FMUL (filled in by the linker)

;------------------------------------------------------------------------------
; n = 3: Sarrus rule.
;------------------------------------------------------------------------------
matdet36_three:
	lea	matdet36_done(pc),a1            ; return to the end

;------------------------------------------------------------------------------
; Determinant of a 3x3 matrix by the Sarrus rule, also used by MAT INV.\nEntry: a2 = matrix (9 packed elements), a1 =
; where to go afterwards\nExit: d0-d2 = determinant
;------------------------------------------------------------------------------
matdet36_three_formula:
	movem.l	(a2),d0-d1                      ; a00
	movem.l	$20(a2),d3-d4                   ; a11
	bsr.s	matdet36_multiply_packed        ; a00 * a11
	movem.l	$40(a2),d3-d4                   ; a22
	bsr.s	matdet36_multiply_by_packed     ; a00 * a11 * a22
	movem.l	d0-d2,(sp)                      ; keep it
	movem.l	$28(a2),d0-d1/d3-d4             ; a12 and a20
	bsr.s	matdet36_multiply_packed        ; a12 * a20
	movem.l	8(a2),d3-d4                     ; a01
	bsr.s	matdet36_multiply_by_packed     ; a01 * a12 * a20
	movem.l	(sp),d3-d5                      ; plus the first term

matdet36_add_second:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_add_second+2 -> FADD (filled in by the linker)
	movem.l	d0-d2,(sp)                      ; keep the sum
	movem.l	$10(a2),d0-d1/d3-d4             ; a02 and a10
	bsr.s	matdet36_multiply_packed        ; a02 * a10
	movem.l	$38(a2),d3-d4                   ; a21
	bsr.s	matdet36_multiply_by_packed     ; a02 * a10 * a21
	movem.l	(sp),d3-d5                      ; plus the sum

matdet36_add_third:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_add_third+2 -> FADD (filled in by the linker)
	movem.l	d0-d2,$c(sp)                    ; sum of the positive terms
	movem.l	$10(a2),d0-d1                   ; a02
	movem.l	$20(a2),d3-d4                   ; a11
	bsr.s	matdet36_multiply_packed        ; a02 * a11
	movem.l	$30(a2),d3-d4                   ; a20
	bsr.s	matdet36_multiply_by_packed     ; a02 * a11 * a20
	movem.l	d0-d2,(sp)                      ; keep it
	movem.l	(a2),d0-d1                      ; a00
	movem.l	$28(a2),d3-d4                   ; a12
	bsr.w	matdet36_multiply_packed        ; a00 * a12
	movem.l	$38(a2),d3-d4                   ; a21
	bsr.w	matdet36_multiply_by_packed     ; a00 * a12 * a21
	movem.l	(sp),d3-d5                      ; plus the last

matdet36_add_fifth:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_add_fifth+2 -> FADD (filled in by the linker)
	movem.l	d0-d2,(sp)                      ; keep the sum
	movem.l	8(a2),d0-d1                     ; a01
	movem.l	$18(a2),d3-d4                   ; a10
	bsr.w	matdet36_multiply_packed        ; a01 * a10
	movem.l	$40(a2),d3-d4                   ; a22
	bsr.w	matdet36_multiply_by_packed     ; a01 * a10 * a22
	movem.l	(sp),d3-d5                      ; plus the sum

matdet36_add_sixth:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_add_sixth+2 -> FADD (filled in by the linker)
	movem.l	$c(sp),d3-d5                    ; positive terms
	bra.w	matdet36_subtract               ; minus the negative terms

;------------------------------------------------------------------------------
; Takes d0 bytes of scratch memory from the LOCAL stack top saved at $20(a6), collecting garbage if it would\nreach the
; string heap.\nEntry: d0 = size\nExit: a0 = start, d0 = end; error 8 if there is no room
;------------------------------------------------------------------------------
matdet36_alloc_scratch:
	movea.l	$20(a6),a0                      ; LOCAL stack top

;------------------------------------------------------------------------------
; As matdet_alloc_scratch, starting at a0.
;------------------------------------------------------------------------------
matdet36_alloc_after:
	add.l	a0,d0                           ; end of the block
	cmp.l	$24(a6),d0                      ; below the string heap?
	bcs.s	matdet36_alloc_done             ; yes

matdet36_collect:
	dc.w	$6100,$0000                     ; bsr.w	matdet36_collect+2 -> GarColl (filled in by the linker)
	cmp.l	$24(a6),d0                      ; room now?
	bcs.s	matdet36_alloc_done             ; yes
	moveq	#8,d0                           ; error 8: out of memory

matdet36_raise_error:
	dc.w	$6000,$0000                     ; bra.w	matdet36_raise_error+2 -> ERROR (filled in by the linker)

matdet36_alloc_done:
	rts                                     ; done

;------------------------------------------------------------------------------
; Returns 1 / d0-d2.\nExit: d0-d2 = reciprocal
;------------------------------------------------------------------------------
matdet36_reciprocal:
	move.l	d0,d3                           ; divisor
	move.l	d1,d4
	move.l	d2,d5

;------------------------------------------------------------------------------
; Returns 1 / d3-d5.
;------------------------------------------------------------------------------
matdet36_one_over:
	move.l	#$80000000,d0                   ; 1.0
	moveq	#0,d1
	move.w	#$3ff,d2

matdet36_tail_fdiv:
	dc.w	$6000,$0000                     ; bra.w	matdet36_tail_fdiv+2 -> FDIV (filled in by the linker)

;------------------------------------------------------------------------------
; MAT INV for n = 1: 1 / the element.
;------------------------------------------------------------------------------
matinv36_one:
	move.l	(a2)+,d3                        ; the element
	movem.w	(a2),d4-d5
	bsr.s	matdet36_one_over               ; 1 / it
	movea.l	$18(sp),a1                      ; result data
	dc.w	$3e3a,$0002                     ; move.w matinv36_one_offset(pc),d7 -> MatOffse (filled in by the
