	neg.w	d2                              ; negated
	bsr.s	matinv36_store_cofactor         ; cofactor 0,0
	movem.l	8(a2),d0-d1                     ; a01
	movem.l	$40(a2),d3-d5                   ; a22
	bsr.w	matdet36_multiply_packed        ; a01 * a22
	movem.l	d0-d2,(a0)                      ; keep it
	movem.l	$38(a2),d0-d1                   ; a21
	movem.l	$10(a2),d3-d4                   ; a02
	bsr.w	matdet36_multiply_packed        ; a21 * a02
	movem.l	(a0),d3-d5                      ; first product
	neg.w	d5                              ; negated
	bsr.w	matinv36_store_cofactor         ; cofactor 0,1
	movem.l	8(a2),d0-d1                     ; a01
	movem.l	$28(a2),d3-d5                   ; a12
