	movem.l	d0-d2,(a0)                      ; keep it
	movem.l	$20(a2),d0-d1                   ; a11
	movem.l	$10(a2),d3-d4                   ; a02
	bsr.w	matdet36_multiply_packed        ; a11 * a02
