	lea	-$50(sp),sp                     ; local frame
	move.l	a1,(sp)                         ; keep the b descriptor

matinv36_check_result:
	dc.w	$6100,$0000                     ; bsr.w	matinv36_check_result+2 -> CHKDIM (filled in by the linker)
