matinv36_result_dims_error:
	dc.w	$6600,$0000                     ; bne.w	matinv36_result_dims_error+2 -> ERR87 (filled in by the linker)
	cmp.w	d1,d2                           ; square?

matinv36_result_square_error:
	dc.w	$6600,$0000                     ; bne.w matinv36_result_square_error+2 -> ERR87 (filled in by the
                                                ;   linker)
	movea.l	(sp),a0                         ; b descriptor

matinv36_check_source:
	dc.w	$6100,$0000                     ; bsr.w	matinv36_check_source+2 -> CHKDIM (filled in by the linker)
	move.l	a1,$1c(sp)                      ; b data
	subq.w	#2,d0                           ; two dimensions?

matinv36_source_dims_error:
	dc.w	$6600,$0000                     ; bne.w	matinv36_source_dims_error+2 -> ERR87 (filled in by the linker)
	cmp.w	d2,d1                           ; square?

matinv36_source_square_error:
	dc.w	$6600,$0000                     ; bne.w matinv36_source_square_error+2 -> ERR87 (filled in by the
                                                ;   linker)
	cmp.w	$20(sp),d1                      ; same size as a?

matinv36_size_error:
	dc.w	$6600,$0000                     ; bne.w	matinv36_size_error+2 -> ERR87 (filled in by the linker)
	movea.l	$1c(sp),a1                      ; b data
	dc.w	$363a,$0002                     ; move.w matinv36_copy(pc),d3 -> MatOffse (filled in by the linker)

matinv36_copy:
