	bpl.s	.compare
	neg.w	d7
.compare:
	cmp.w	d6,d7                           ; larger exponent?
	bgt.s	.new_best                       ; yes: new best
	blt.s	.next_row                       ; smaller: skip
	cmp.l	d0,d2                           ; same: compare the mantissas
	bcs.s	.next_row                       ; smaller
	bne.s	.new_best                       ; larger
